window.__EBT=window.__EBT||{};window.__EBT["ro"]=window.__EBT["ro"]||{};window.__EBT["ro"]["Deut"]=[[1,[[1,"Acestea sunt cuvintele pe care Moise le-a spus întregului Israel dincolo de Iordan, în pustie, în Araba, vizavi de Suf, între Paran, Tofel, Laban, Hazerot și Dizahab."],[2,"Este de unsprezece zile de călătorie de la Horeb pe drumul muntelui Seir până la Cades Barnea."],[3,"În al patruzecilea an, în luna a unsprezecea, în prima zi a lunii, Moise a vorbit copiilor lui Israel, după tot ce i-a dat Domnul prin poruncă:"],[4,"după ce a lovit pe Sihon, împăratul amoriților, care locuia în Heșbon, și pe Og, împăratul Basanului, care locuia în Aștarot, la Edrei."],[5,"Dincolo de Iordan, în țara Moabului, Moise a început să spună această lege, zicând:"],[6,"„Domnul, Dumnezeul nostru, ne-a vorbit în Horeb, zicând: „Ați locuit destul de mult pe muntele acesta."],[7,"Întoarceți-vă și porniți-vă și mergeți în țara de deal a Amoriților și în toate locurile din apropiere: în Araba, în țara de deal, în câmpie, în sud, pe malul mării, în țara canaaniților și în Liban până la râul cel mare, râul Eufrat."],[8,"Iată, am pus țara înaintea ta. Intră și stăpânește țara pe care DOMNUL a jurat-o părinților tăi, lui Avraam, Isaac și Iacov, că le va da lor și semințelor lor după ei.”"],[9,"Ți-am vorbit în acel moment, spunând: „Nu sunt în stare să te suport singur."],[10,"Domnul, Dumnezeul tău, te-a înmulțit și iată că ești astăzi ca stelele cerului în mulțime."],[11,"Domnul, Dumnezeul părinţilor voştri, să vă facă de o mie de ori mai mulţi cât sunteţi şi să vă binecuvânteze, precum v-a promis!"],[12,"Cum pot eu singur să suport problemele tale, poverile și conflictele tale?"],[13,"Luați oameni înțelepți, înțelepți, care sunt respectați printre semințiile voastre și îi voi pune capete peste voi.”"],[14,"Tu mi-ai răspuns și ai zis: „Ceea ce ai spus este bine să faci”."],[15,"Așa că am luat căpeteniile semințiilor voastre, oameni înțelepți și stimați, și i-am pus căpetenii peste voi, căpetenii de mii, căpetenii de sute, căpetenii de cincizeci, căpetenii de zeci și căpetenii, după semințiile voastre."],[16,"Le-am poruncit judecătorilor voștri în vremea aceea, spunând: „Ascultați cauzele dintre frații voștri și judecați drept între un om și fratele lui și străinul care locuiește cu el."],[17,"Să nu arăți părtinire în judecată; veți auzi pe cei mici și pe cei mari deopotrivă. Să nu vă fie frică de fața omului, căci judecata este a lui Dumnezeu. Cazul care este prea greu pentru tine, să mi-o aduci și eu îl voi auzi.”"],[18,"Ți-am poruncit în vremea aceea toate lucrurile pe care ar trebui să le faci."],[19,"Am plecat de la Horeb și am străbătut toată pustia aceea mare și înfricoșătoare pe care ai văzut-o, pe drumul către muntele amoriților, așa cum ne-a poruncit Domnul Dumnezeul nostru; şi am ajuns la Cades Barnea."],[20,"Ți-am spus: „Ați venit în muntele amoriților, pe care ni-l dă Domnul Dumnezeul nostru."],[21,"Iată, Domnul Dumnezeul tău a pus țara înaintea ta. Suie-te, ia în stăpânire, precum ți-a spus Domnul, Dumnezeul părinților tăi. Nu-ți fie frică și nici nu te speria.”"],[22,"Voi v-ați apropiat de mine, fiecare dintre voi, și ați zis: „Să trimitem oameni înaintea noastră, ca să cerceteze țara pentru noi și să ne aducă înapoi calea pe care trebuie să ne urcăm și cetățile în care vom ajunge.”"],[23,"Chestia m-a încântat bine. Am luat doisprezece dintre oamenii tăi, un bărbat pentru fiecare trib."],[24,"S-au întors și s-au urcat în munții și au ajuns în valea Eșcol și au văzut-o."],[25,"Ei au luat în mâinile lor o parte din rodul țării și ni l-au dus și ne-au adus din nou cuvânt și au zis: „Este o țară bună pe care ne-o dă Domnul, Dumnezeul nostru.”"],[26,"Dar tu nu te-ai urcat, ci te-ai răzvrătit împotriva poruncii Domnului, Dumnezeului tău."],[27,"Ai murmurat în corturile tale și ai zis: „Pentru că Domnul ne urăște, ne-a scos din țara Egiptului, ca să ne dea în mâinile amoriților, ca să ne nimicească."],[28,"Unde urcăm? Frații noștri ne-au făcut inima să se topească, spunând: „Oamenii sunt mai mari și mai înalți decât noi. Orașele sunt mari și întărite până la cer. Mai mult, am văzut acolo pe fiii anaciților!”"],[29,"Atunci v-am spus: „Nu vă înspăimântați, nu vă temeți de ei."],[30,"Domnul Dumnezeul tău, care merge înaintea ta, va lupta pentru tine, după tot ce a făcut pentru tine în Egipt, sub ochii tăi,"],[31,"și în pustiul unde ai văzut cum te-a purtat Domnul, Dumnezeul tău, așa cum își poartă un om pe fiul său, pe tot drumul pe care ai mers, până ai ajuns în locul acesta.”"],[32,"Dar în acest lucru n-ai crezut în Domnul Dumnezeul tău,"],[33,"care mergea înaintea ta pe drum, ca să găsească un loc în care să-ți așezi corturile: noaptea în foc, ca să-ți arate pe ce cale să mergi, și ziua în nor."],[34,"Domnul a auzit glasul cuvintelor tale și s-a mâniat și a jurat, zicând:"],[35,"„Cu siguranță niciunul dintre acești oameni din această generație rea nu va vedea țara bună pe care am jurat că o voi da părinților voștri,"],[36,"cu excepția lui Caleb, fiul lui Iefune. El va vedea. Îi voi da lui și copiilor săi țara pe care a călcat-o, pentru că a urmat pe deplin pe Domnul.”"],[37,"De asemenea, Domnul S-a mâniat pe mine din pricina voastră, și a zis: „Nici voi să nu intrați acolo."],[38,"Iosua, fiul lui Nun, care stă înaintea ta, va intra acolo. Încurajează-l, căci el va lăsa pe Israel să-l moștenească."],[39,"Mai mult, micuții tăi, despre care ai spus că vor fi prinși sau uciși, copiii tăi, care astăzi nu au cunoștință de bine sau de rău, vor intra acolo. le voi da și ei o vor stăpâni."],[40,"Dar în ceea ce vă privește, întoarceți-vă și porniți-vă în pustie, pe drumul spre Marea Roșie.”"],[41,"Atunci tu ai răspuns și mi-ai zis: „Am păcătuit împotriva Domnului, ne vom sui și ne vom lupta, după tot ce ne-a poruncit Domnul, Dumnezeul nostru.” Fiecare dintre voi și-a îmbrăcat armele de război și s-a gândit să urce în țara de deal."],[42,"Domnul mi-a zis: „Spune-le: „Nu vă urcați și nu vă luptați, căci eu nu sunt printre voi, ca să nu fiți loviți de vrăjmașii voștri.”"],[43,"Așa că ți-am vorbit și nu ai ascultat; dar te-ai răzvrătit împotriva poruncii Domnului, ai fost îndrăzneț și te-ai suit pe munte."],[44,"Amoriții, care locuiau în acea țară de deal, au ieșit împotriva ta și te-au urmărit ca albinele și te-au doborât în ​​Seir, până la Horma."],[45,"Te-ai întors și ai plâns înaintea Domnului, dar Domnul nu ți-a ascultat glasul și nu și-a întors urechea către tine."],[46,"Așa că ai stat în Cades multe zile, după zilele în care ai rămas."]]],[2,[[1,"Apoi ne-am întors și am pornit în pustie, pe drumul spre Marea Roșie, așa cum mi-a spus Domnul; și am înconjurat muntele Seir multe zile."],[2,"Domnul mi-a vorbit, zicând:"],[3,"„Ai înconjurat acest munte destul de mult. Întoarce-te spre nord."],[4,"Poruncește poporului, zicând: „Să treci hotarul fraților tăi, copiii lui Esau, care locuiesc în Seir; și le va fi frică de tine. Prin urmare, aveți grijă."],[5,"Nu te certa cu ei; căci nu vă voi da nimic din pământul lor, nu, nici măcar pentru călcarea piciorului, pentru că am dat muntele Seir lui Esau ca stăpânire."],[6,"Să cumperi mâncare de la ei pe bani, ca să mănânci. Să cumperi și de la ei apă pe bani, ca să bei.”"],[7,"Căci Domnul Dumnezeul tău te-a binecuvântat în toată lucrarea mâinilor tale. El a cunoscut mersul tău prin această mare sălbăticie. În acești patruzeci de ani, Domnul Dumnezeul tău a fost cu tine. Nu ți-a lipsit nimic."],[8,"Așa că am trecut de la frații noștri, copiii lui Esau, care locuiesc în Seir, de pe drumul Arabei din Elat și din Ețion-Gheber. Ne-am întors și am trecut pe calea pustiei Moabului."],[9,"Domnul mi-a zis: „Nu deranjați Moabul și nu vă certați cu ei în luptă, căci nu vă voi da stăpânire din țara lui, pentru că am dat Ar fiilor lui Lot ca stăpânire.”"],[10,"(Emimii au locuit acolo înainte, un popor mare și numeros și înalt ca anachimii."],[11,"Aceștia sunt, de asemenea, considerați a fi Refaim, ca anaci; dar moabiții le numesc Emim."],[12,"Horiții au locuit și în trecut în Seir, dar copiii lui Esau le-au urmat. I-au nimicit dinaintea lor și au locuit în locul lor, așa cum a făcut Israel cu țara stăpânirii sale, pe care le-a dat-o Domnul.)"],[13,"„Acum ridică-te și treci peste pârâul Zered.” Am trecut peste pârâul Zered."],[14,"Zilele în care am venit de la Cades Barnea până am trecut peste pârâul Zered au fost treizeci și opt de ani, până când toată generația bărbaților de război s-a mistuit din mijlocul taberei, precum le-a jurat Domnul."],[15,"Mai mult, mâna Domnului a fost împotriva lor, ca să-i nimicească din mijlocul taberei, până când au fost mistuiți."],[16,"Deci, când toți oamenii de război au fost mistuiți și morți din mijlocul poporului,"],[17,"Domnul mi-a vorbit, zicând:"],[18,"„Astăzi vei trece peste Ar, hotarul Moabului."],[19,"Când te apropii de hotarul fiilor lui Amon, nu-i deranja și nu te certa cu ei; căci nu vă voi da în stăpânire niciunul din țara copiilor lui Amon, pentru că am dat-o fiilor lui Lot ca stăpânire.”"],[20,"(De asemenea, aceasta este considerată o țară a lui Refaim. Refaim a locuit acolo în trecut, dar amoniții le numesc Zamzummim,"],[21,"un popor mare, multe și înalte, ca anacii; dar Domnul i-a nimicit dinaintea lui Israel și ei le-au urmat și au locuit în locul lor,"],[22,"așa cum a făcut pentru copiii lui Esau, care locuiesc în Seir, când a nimicit pe Horiți dinaintea lor; și le-au urmat și au locuit în locul lor și până în ziua de azi."],[23,"Apoi avimii, care locuiau în sate până în Gaza: caphtorimii, care au ieșit din Caphtor, i-au nimicit și au locuit în locul lor.)"],[24,"„Ridică-te, pornește-te și treci peste valea Arnonului. Iată, am dat în mâinile tale pe Sihon Amoritul, regele Hesbonului, și țara lui; începe să o stăpânești și să lupți cu el în luptă."],[25,"Astăzi voi începe să pun frica față de tine și frica față de tine asupra popoarelor care sunt sub tot cerul, care vor auzi vestea ta și se vor cutremura și vor fi întristați din cauza ta.”"],[26,"Am trimis soli din pustia Chedemot la Sihon, regele Hesbonului, cu cuvinte de pace, spunând:"],[27,"„Lasă-mă să trec prin țara ta, voi merge pe drum, nu mă voi întoarce nici la dreapta, nici la stânga."],[28,"Să-mi vinzi mâncare pe bani, ca să mănânc; și dă-mi apă pentru bani, ca să beau. Lasă-mă să trec pe picioare,"],[29,"cum mi-au făcut copiii lui Esau, care locuiesc în Seir, și moabiții care locuiesc în Ar, până când voi trece Iordanul în țara pe care ne-o dă Domnul Dumnezeul nostru.”"],[30,"Dar Sihon, împăratul Hesbonului, nu ne-a lăsat să trecem pe lângă el, căci Domnul Dumnezeul tău și-a împietrit duhul și i-a îndărătnit inima, ca să-l dea în mâna ta, așa cum este astăzi."],[31,"Domnul mi-a zis: „Iată, am început să dau înaintea ta pe Sihon și țara lui. Începe să stăpânești, ca să moștenești țara lui.”"],[32,"Atunci Sihon a ieșit împotriva noastră, el și tot poporul său, să lupte la Iahaz."],[33,"Domnul Dumnezeul nostru l-a dat înaintea noastră; și l-am lovit pe el, pe fiii lui și pe tot poporul lui."],[34,"Am luat toate cetățile lui în vremea aceea și am distrus cu desăvârșire toate cetățile locuite, cu femeile și cu cei mici. Nu am lăsat pe nimeni."],[35,"Numai vitele le-am luat ca pradă pentru noi, cu prada cetăţilor pe care le-am luat."],[36,"De la Aroer, care este la marginea văii Arnonului, și de la cetatea care este în vale, până la Galaad, nu era o cetate prea înaltă pentru noi. Domnul Dumnezeul nostru a dat totul înaintea noastră."],[37,"Numai de țara copiilor lui Amon nu te-ai apropiat: de toate malurile râului Iaboc și de cetățile munților și oriunde ne-a interzis Domnul Dumnezeul nostru."]]],[3,[[1,"Apoi ne-am întors și am urcat pe drumul către Basan. Og, împăratul Basanului, a ieșit împotriva noastră, el și tot poporul său, să lupte la Edrei."],[2,"Domnul mi-a zis: „Nu te teme de el, căci l-am dat în mâinile tale pe el, cu tot poporul lui și țara lui. Să-i faci așa cum i-ai făcut lui Sihon, împăratul amoriților, care locuia la Heșbon.”"],[3,"Astfel, Domnul Dumnezeul nostru a dat și în mâinile noastre pe Og, împăratul Basanului, și pe tot poporul său. L-am lovit până când nu i-a mai rămas nimeni."],[4,"Am luat toate orașele lui în acel moment. Nu a fost o cetate pe care să nu le luăm de la ei: şaizeci de cetăţi, toată regiunea Argobului, împărăţia lui Og în Basan."],[5,"Toate acestea erau cetăți întărite cu ziduri înalte, porți și zăbrele, pe lângă multe sate fără ziduri."],[6,"I-am nimicit cu desăvârșire, așa cum am făcut-o lui Sihon, împăratul Heșbonului, nimicind cu desăvârșire orice cetate locuită, cu femeile și cu cei mici."],[7,"Dar toate vitele și prada cetăților le-am luat drept pradă pentru noi."],[8,"Am luat țara în vremea aceea din mâna celor doi împărați ai amoriților care erau dincolo de Iordan, de la valea Arnonului până la muntele Hermon."],[9,"(Sidonienii îl numesc pe Hermon Sirion, iar amoriții îl numesc Senir.)"],[10,"Am luat toate cetățile câmpiei, tot Galaadul și tot Basanul, până la Saleca și Edrei, cetăți ale împărăției lui Og în Basan."],[11,"(Căci numai Og, regele Basanului, a rămas din rămășița Refaimilor. Iată, patul lui era un pat de fier. Nu este oare în Raba copiilor lui Amon? Lungimea lui de nouă coți și lățimea de patru coți, după un cot de om.)"],[12,"Țara aceasta pe care am luat-o în stăpânire în vremea aceea: din Aroer, care este lângă valea Arnonului, și jumătate din muntele Galaadului cu cetățile ei, am dat-o rubeniților și gadiților;"],[13,"și restul Galaadului și tot Basanul, împărăția lui Og, i-am dat jumătății de seminție a lui Manase, toată regiunea Argob, chiar tot Basanul. (Aceeași se numește țara lui Refaim."],[14,"Iair, fiul lui Manase, a luat toată regiunea Argob, până la hotarul Gheșuriților și Maacatiților, și le-a numit Basan, după numele său, Havvoth Iair, până astăzi.)"],[15,"I-am dat Galaad lui Machir."],[16,"Rubeniților și Gadiților le-am dat din Galaad până la valea Arnonului, mijlocul văii și hotarul ei, până la râul Iaboc, care este hotarul fiilor lui Amon;"],[17,"de asemenea, Araba și Iordanul și hotarul lui, de la Chineret până la marea Arabei, Marea Sărată, sub poalele Pisga, spre răsărit."],[18,"Ți-am poruncit în vremea aceea, zicând: „Domnul, Dumnezeul vostru, v-a dat țara aceasta ca să o stăpâniți: voi toți, bărbați viteji, veți trece înarmați înaintea fraților voștri, copiii lui Israel."],[19,"Dar soțiile voastre, copiii voștri și vitele voastre (știu că aveți multe vite) vor locui în cetățile voastre pe care vi le-am dat,"],[20,"până când Domnul va da odihnă fraților voștri, ca și vouă, și ei vor stăpâni și țara pe care le-o dă Domnul Dumnezeul vostru dincolo de Iordan. Atunci fiecare să vă întoarceți în stăpânirea lui, pe care vi le-am dat.”"],[21,"I-am poruncit lui Iosua în vremea aceea, spunând: „Ochii tăi au văzut tot ce a făcut Domnul, Dumnezeul tău, acestor doi împărați. Așa va face Domnul tuturor împărățiilor pe care vei trece."],[22,"Să nu te temi de ei; căci Domnul Dumnezeul tău Însuși luptă pentru tine.”"],[23,"L-am implorat pe Domnul în vremea aceea, zicând:"],[24,"„Doamne, Doamne, ai început să arăți robului Tău măreția Ta și mâna Ta puternică, căci ce dumnezeu este în cer sau pe pământ, care să facă fapte ca ale Tale și fapte puternice ca ale Tale?"],[25,"Te rog, lasă-mă să trec și să văd țara bună de dincolo de Iordan, muntele acela minunat și Libanul.”"],[26,"Dar Domnul S-a supărat pe mine din cauza ta și nu m-a ascultat. Domnul mi-a zis: „Ajunge, nu-mi mai vorbi despre aceasta."],[27,"Urcă-te în vârful Pisga, ridică-ți ochii spre apus și spre nord, spre sud și spre est și vezi cu ochii; căci nu vei trece peste acest Iordan."],[28,"Dar încredințează-l pe Iosua, încurajează-l și întărește-l; căci el va trece înaintea acestui popor și-i va lăsa să moștenească țara pe care o vei vedea.”"],[29,"Așa că am rămas în valea de lângă Beth Peor."]]],[4,[[1,"Acum, Israele, ascultă legile și poruncile pe care te învăț, să le împlinești, ca să trăiești, să intri și să stăpânești țara pe care ți-o dă Domnul, Dumnezeul părinților tăi."],[2,"Să nu adaugi la cuvântul pe care ți-l poruncesc și să nu-l iei, ca să păzești poruncile Domnului Dumnezeului tău, pe care ți le poruncesc."],[3,"Ochii tăi au văzut ce a făcut Domnul din pricina lui Baal Peor; căci DOMNUL Dumnezeul tău a nimicit din mijlocul tău pe toți oamenii care urmau lui Baal-Peor."],[4,"Dar voi, care ați fost credincioși Domnului, Dumnezeului vostru, sunteți toți vii astăzi."],[5,"Iată, v-am învățat legile și poruncile, așa cum mi-a poruncit Domnul Dumnezeul meu, ca să faceți așa în mijlocul țării în care intrați ca să o stăpâniți."],[6,"Păstrați deci și faceți-le; pentru că aceasta este înțelepciunea și priceperea ta în fața popoarelor, care vor asculta toate aceste legi și vor zice: „Cu siguranță acest neam mare este un popor înțelept și înțelept.”"],[7,"Căci ce națiune mare este care să aibă un dumnezeu atât de aproape de ei precum este Domnul Dumnezeul nostru ori de câte ori Îl chemăm?"],[8,"Ce națiune mare este care are legile și poruncile atât de drepte ca toată această lege pe care ți-o pun astăzi înainte?"],[9,"Numai ai grijă și păzește-ți sufletul cu sârguință, ca să nu uiți lucrurile pe care le-au văzut ochii tăi și să nu se îndepărteze din inima ta în toate zilele vieții tale; ci fă-le cunoscute copiilor tăi și copiilor tăi,"],[10,"în ziua în care ai stat înaintea Domnului Dumnezeului tău în Horeb, când Domnul mi-a zis: „Adună poporul la Mine și îi voi face să asculte cuvintele Mele, ca să învețe să se teamă de Mine în toate zilele cât trăiesc pe pământ și să-și învețe copiii.”"],[11,"Te-ai apropiat și ai stat sub munte. Muntele a ars cu foc până în inima cerului, cu întuneric, nor și întuneric gros."],[12,"Domnul ți-a vorbit din mijlocul focului: ai auzit glasul cuvintelor, dar n-ai văzut nicio formă; ai auzit doar o voce."],[13,"El ți-a spus legământul Său, pe care ți-a poruncit să-l împliniți, chiar și cele zece porunci. Le-a scris pe două tăblițe de piatră."],[14,"Domnul mi-a poruncit în vremea aceea să vă învăț legile și poruncile, ca să le împliniți în țara pe care o treceți ca să o stăpâniți."],[15,"Fii foarte atent, căci n-ai văzut nicio formă în ziua în care ți-a vorbit Domnul în Horeb din mijlocul focului,"],[16,"ca nu cumva să vă stricați și să vă faceți un chip cioplit sub forma vreunei figuri, asemănător masculin sau feminin,"],[17,"asemănarea oricărui animal care este pe pământ, asemănarea oricărei păsări înaripate care zboară pe cer,"],[18,"asemănarea cu orice se târăște pe pământ, asemănarea oricărui pește care se află în apa sub pământ;"],[19,"ca nu cumva să-ți ridici ochii spre cer și, când vei vedea soarele și luna și stelele, chiar toată oștirea cerului, să fii atras și să te închini lor și să le slujești, pe care Domnul Dumnezeul tău le-a dat tuturor popoarelor de sub tot cerul."],[20,"Dar Domnul te-a luat și te-a scos din cuptorul de fier, din Egipt, ca să-i fii popor de moștenire, așa cum este astăzi."],[21,"În plus, DOMNUL S-a mâniat pe mine din pricina voastră și a jurat că nu voi trece Iordanul și că nu voi intra în țara cea bună pe care ți-o dă ca moștenire Domnul Dumnezeul tău;"],[22,"dar trebuie să mor pe pământul acesta. Nu trebuie să trec Iordanul, dar tu vei trece și vei stăpâni țara aceea bună."],[23,"Aveți grijă să nu uitați legământul Domnului, Dumnezeului vostru, pe care l-a încheiat cu voi și să vă faceți un chip cioplit în chipul a ceea ce v-a interzis Domnul, Dumnezeul vostru."],[24,"Căci Domnul Dumnezeul tău este un foc mistuitor, un Dumnezeu gelos."],[25,"Când veți avea copii și fii ai copiilor și veți fi mult timp în țară, și atunci vă veți strică și vă faceți un chip cioplit sub formă de orice și faceți ce este rău înaintea Domnului, Dumnezeului vostru, ca să-l înfurieți,"],[26,"Chem astăzi cerul și pământul să mărturisească împotriva ta, că în curând vei pieri complet din țara pe care o treci peste Iordan ca să o stăpânești. Nu-ți vei prelungi zilele pe el, ci vei fi distrus cu totul."],[27,"Domnul vă va împrăștia printre popoare și veți rămâne puțini la număr printre neamurile de unde vă va duce Domnul."],[28,"Acolo vei sluji zeilor, lucrare a mâinilor oamenilor, din lemn și piatră, care nici nu văd, nici nu aud, nici nu mănâncă, nici nu miros."],[29,"Dar de acolo vei căuta pe Domnul, Dumnezeul tău, și-l vei găsi când îl vei căuta din toată inima ta și din tot sufletul tău."],[30,"Când ești în asuprire și toate aceste lucruri s-au întâmplat asupra ta, în zilele din urmă te vei întoarce la Domnul, Dumnezeul tău, și vei asculta glasul Lui."],[31,"Căci Domnul Dumnezeul tău este un Dumnezeu milostiv. El nu te va pierde, nici nu te va nimici, nici nu va uita legământul părinţilor tăi pe care le-a jurat."],[32,"Întrebați acum despre zilele trecute, care au fost înaintea voastră, din ziua în care Dumnezeu a creat omul pe pământ și de la un capăt la altul al cerului, dacă a fost ceva la fel de mare ca acest lucru sau s-a auzit ca acesta?"],[33,"A auzit vreodată un popor glasul lui Dumnezeu vorbind din mijlocul focului, așa cum ați auzit și voi, și a trăit?"],[34,"Sau a încercat Dumnezeu să meargă și să ia pentru sine un neam din mijlocul altui neam, prin încercări, prin semne, prin minuni, prin război, cu o mână puternică, cu un braț întins și cu groază mari, după tot ce a făcut Domnul Dumnezeul tău pentru tine în Egipt înaintea ochilor tăi?"],[35,"Ți-a fost arătat ca să știi că Domnul este Dumnezeu. Nu mai este nimeni în afară de el."],[36,"Din cer te-a făcut să-I auzi glasul, ca să te învețe. Pe pământ te-a făcut să-i vezi focul cel mare; și ai auzit cuvintele lui din mijlocul focului."],[37,"Pentru că i-a iubit pe părinții voștri, de aceea a ales sămânța lor după ei și v-a scos din Egipt cu prezența Lui, cu puterea Lui mare;"],[38,"să alunge dinaintea ta neamuri mai mari și mai puternice decât tine, să te aducă înăuntru, să-ți dea țara lor ca moștenire, așa cum este astăzi."],[39,"Să știți deci astăzi și să țineți cont de faptul că Domnul însuși este Dumnezeu sus în ceruri și jos pe pământ. Nu este nimeni altcineva."],[40,"Să păzești legile și poruncile Lui pe care ți le poruncesc astăzi, ca să-ți fie bine ție și copiilor tăi după tine și să-ți prelungești zilele în țara pe care ți-o dă Domnul Dumnezeul tău pentru totdeauna."],[41,"Atunci Moise a pus deoparte trei cetăți dincolo de Iordan, spre răsăritul soarelui,"],[42,"ca să fugă acolo ucigașul, care își ucide aproapele fără să vrea și nu l-a urât în ​​vremurile trecute și, fugind în una dintre aceste orașe, să trăiască:"],[43,"Bezer în pustie, în câmpie, pentru Rubeniți; și Ramot în Galaad pentru Gadiți; și Golan în Basan pentru Manasiți."],[44,"Aceasta este legea pe care Moise a pus-o înaintea copiilor lui Israel."],[45,"Acestea sunt mărturiile, legile și rânduielile pe care le-a spus Moise copiilor lui Israel când au ieșit din Egipt:"],[46,"dincolo de Iordan, în valea vizavi de Bet-Peor, în țara lui Sihon, împăratul amoriților, care locuia la Heșbon, pe care Moise și copiii lui Israel l-au lovit când au ieșit din Egipt."],[47,"Ei au luat în stăpânire țara lui și țara lui Og, regele Basanului, cei doi împărați ai amoriților, care erau dincolo de Iordan, spre răsăritul soarelui;"],[48,"de la Aroer, care este la marginea văii Arnon, până la muntele Siyon (numit și Hermon),"],[49,"și toată zona de dincolo de Iordan, spre răsărit, până la marea Arabei, sub poalele Pisga."]]],[5,[[1,"Moise a chemat pe tot Israelul și le-a zis: „Ascultă, Israele, legile și rânduielile pe care le spun astăzi în urechile tale, ca să le înveți și să păziți să le împliniți.”"],[2,"Domnul Dumnezeul nostru a făcut un legământ cu noi în Horeb."],[3,"Domnul nu a făcut acest legământ cu părinţii noştri, ci cu noi, chiar cu noi, care suntem cu toţii aici în viaţă astăzi."],[4,"Domnul a vorbit cu tine față în față pe munte din mijlocul focului,"],[5,"(Am stat între Domnul și voi în vremea aceea, ca să vă arăt cuvântul Domnului; căci v-ați speriat de foc și nu v-ați urcat pe munte) și am zis:"],[6,"„Eu sunt Domnul Dumnezeul tău, care te-am scos din țara Egiptului, din casa robiei."],[7,"„Să nu ai alți dumnezei înaintea mea."],[8,"„Să nu-ți faci chip cioplit, nicio asemănare cu ceea ce este sus în cer sau cu ce este dedesubt pe pământ, sau cu ce este în apa sub pământ."],[9,"Să nu te închini înaintea lor și să nu le slujești, căci Eu, Iehova, Dumnezeul tău, sunt un Dumnezeu gelos, care pedepsesc nelegiuirea părinților asupra copiilor și pe al treilea și pe al patrulea neam al celor ce Mă urăsc."],[10,"și arătând bunătate iubitoare față de mii de cei care mă iubesc și păzesc poruncile mele."],[11,"„Să nu folosești greșit numele Domnului Dumnezeului tău, căci Domnul nu-l va ține nevinovat pe cel care folosește greșit numele lui."],[12,"„Păzește ziua Sabatului, ca să o sfințești, așa cum ți-a poruncit Domnul, Dumnezeul tău."],[13,"Să lucrezi șase zile și să-ți faci toată lucrarea;"],[14,"dar ziua a șaptea este Sabatul Domnului, Dumnezeului tău, în care să nu faci nicio lucrare: nici tu, nici fiul tău, nici fiica ta, nici robul tău, nici roaba ta, nici boul tău, nici măgarul tău, nici vreunul din vitele tale, nici străinul tău care este în porțile tale; ca slujitorul tău și roaba ta să se odihnească la fel de bine ca tine."],[15,"Să-ți aduci aminte că ai fost slujitor în țara Egiptului și că Domnul Dumnezeul tău te-a scos de acolo cu o mână puternică și cu un braț întins. De aceea, Domnul Dumnezeul tău ți-a poruncit să păzești ziua Sabatului."],[16,"„Cinstește pe tatăl tău și pe mama ta, așa cum ți-a poruncit Domnul, Dumnezeul tău, pentru ca zilele tale să fie lungi și să-ți fie bine în țara pe care ți-o dă Domnul, Dumnezeul tău."],[17,"„Să nu ucizi."],[18,"„Să nu comite adulter."],[19,"„Să nu furi."],[20,"„Să nu dai mărturie mincinoasă împotriva aproapelui tău."],[21,"„Să nu poftești de soția aproapelui tău, nici să nu poftești casa aproapelui tău, câmpul lui, nici robul lui, nici roaba lui, nici boul lui, nici măgarul lui, nici orice este al aproapelui tău.”"],[22,"Domnul a rostit aceste cuvinte întregii adunări tale de pe munte, din mijlocul focului, al norului și al întunericului, cu glas mare. Nu a mai adăugat. El le-a scris pe două tăblițe de piatră și mi le-a dat."],[23,"Când ai auzit glasul din mijlocul întunericului, pe când muntele ardea cu foc, te-ai apropiat de mine, toți căpeteniile semințiilor tale și bătrânii tăi;"],[24,"și ai zis: „Iată, Domnul Dumnezeul nostru ne-a arătat slava și măreția Sa și am auzit glasul Lui din mijlocul focului. Am văzut astăzi că Dumnezeu vorbește cu oamenii și el trăiește."],[25,"Acum, așadar, de ce să murim? Căci acest mare foc ne va mistui. Dacă mai auzim glasul Domnului Dumnezeului nostru, atunci vom muri."],[26,"Căci cine este din orice făptură care a auzit glasul Dumnezeului celui viu vorbind din mijlocul focului, ca și noi, și a trăit?"],[27,"Apropiați-vă și ascultați tot ce va spune Domnul, Dumnezeul nostru, și spuneți-ne tot ce vă spune Domnul, Dumnezeul nostru; și o vom auzi și o vom face.”"],[28,"Domnul a auzit glasul cuvintelor tale când mi-ai vorbit; și Domnul mi-a zis: „Am auzit glasul cuvintelor acestui popor, pe care ți le-au spus, și bine au spus tot ce au spus."],[29,"O, dacă ar fi în ei o asemenea inimă, încât să se teamă de mine și să păzească mereu toate poruncile Mele, ca să fie bine lor și copiilor lor pentru totdeauna!"],[30,"„Du-te și spune-le: „Întoarceți-vă la corturile voastre”."],[31,"Dar tu, stai aici lângă mine și îți voi spune toate poruncile, legile și rânduielile pe care le vei învăța, ca să le împlinească în țara pe care le dau în stăpânire.”"],[32,"Vei avea grijă să faci așa cum ți-a poruncit Domnul, Dumnezeul tău. Să nu te întorci la dreapta sau la stânga."],[33,"Să umbli pe tot calea pe care ți-a poruncit Domnul, Dumnezeul tău, ca să trăiești și să-ți fie bine și să-ți prelungești zilele în țara pe care o vei stăpâni."]]],[6,[[1,"Acestea sunt poruncile, legile și rânduielile pe care DOMNUL Dumnezeul tău a poruncit să te învețe, ca să le împlinești în țara pe care vei trece să o stăpânești;"],[2,"ca să te temi de Domnul, Dumnezeul tău, să păzești toate legile și poruncile Lui, pe care ți le poruncesc, tu, fiul tău și fiul fiului tău, în toate zilele vieții tale; și ca zilele tale să fie prelungite."],[3,"Ascultă deci, Israele, și ai grijă să faci asta, ca să-ți fie bine și să te înmulți cu putere, așa cum ți-a făgăduit Domnul, Dumnezeul părinților tăi, într-o țară în care curge lapte și miere."],[4,"Ascultă, Israele: Domnul este Dumnezeul nostru. Yahweh este unul."],[5,"Să iubești pe Domnul Dumnezeul tău din toată inima ta, din tot sufletul tău și din toată puterea ta."],[6,"Aceste cuvinte, pe care ți le poruncesc astăzi, vor fi în inima ta;"],[7,"și să le înveți cu sârguință copiilor tăi și să vorbești despre ei când vei sta în casa ta și când vei merge pe drum, când te vei culca și când te vei scula."],[8,"Le vei lega ca semn pe mâna ta, iar ele vor fi ca frunte între ochi."],[9,"Le vei scrie pe stâlpii casei tale și pe porțile tale."],[10,"Când Domnul Dumnezeul tău te va aduce în țara pe care a jurat părinților tăi, lui Avraam, Isaac și Iacov, că îți va da cetăți mari și frumoase, pe care nu le-ai zidit tu,"],[11,"și case pline cu toate lucrurile bune pe care nu le-ați umplut și cisterne săpate, pe care nu le-ați săpat, vii și măslini pe care nu i-ați sădit, și veți mânca și vă veți sătura;"],[12,"atunci păziți-vă să nu uitați pe Domnul, care v-a scos din țara Egiptului, din casa robiei."],[13,"Să te temi de Domnul Dumnezeul tău; și să-i slujiți și să jurați pe numele lui."],[14,"Să nu mergi după alți dumnezei, dintre zeii popoarelor care sunt în jurul tău,"],[15,"căci DOMNUL Dumnezeul tău dintre voi este un Dumnezeu gelos, ca să nu se aprindă mânia Domnului Dumnezeului vostru împotriva voastră și să vă nimicească de pe suprafața pământului."],[16,"Să nu ispitești pe Domnul Dumnezeul tău, așa cum l-ai ispitit în Masa."],[17,"Să păzești cu sârguință poruncile Domnului, Dumnezeului tău, și mărturiile Lui și legile Lui, pe care ți le-a poruncit."],[18,"Să faceți ce este drept și bine înaintea Domnului, ca să vă fie bine și să intrați și să stăpâniți țara bună pe care Domnul a jurat-o părinților voștri,"],[19,"ca să-ți alunge pe toți vrăjmașii tăi dinaintea ta, precum a spus Domnul."],[20,"Când fiul tău te va întreba, la vremea viitoare, zicând: „Ce înseamnă mărturiile, legile și rânduielile pe care ți le-a poruncit Domnul Dumnezeul nostru?”"],[21,"apoi îi vei spune fiului tău: „Noi am fost robii lui Faraon în Egipt. Domnul ne-a scos din Egipt cu mână puternică;"],[22,"și Domnul a făcut semne și minuni mari și înfricoșătoare asupra Egiptului, asupra Faraonului și asupra întregii sale case, înaintea ochilor noștri;"],[23,"şi ne-a scos de acolo, ca să ne aducă înăuntru, ca să ne dea ţara pe care a jurat-o părinţilor noştri."],[24,"Domnul ne-a poruncit să împlinim toate aceste porunci, să ne temem de Domnul Dumnezeul nostru, spre binele nostru mereu, ca să ne țină în viață, așa cum suntem astăzi."],[25,"Ne va fi dreptate dacă vom avea grijă să împlinim toate aceste porunci înaintea Domnului, Dumnezeului nostru, așa cum ne-a poruncit El.”"]]],[7,[[1,"Când Domnul Dumnezeul tău te va aduce în țara în care vei merge să o stăpânești și va alunga dinaintea ta multe neamuri: hetiții, ghirgasiții, amoriții, canaaniții, fereziții, heviții și iebusiții, șapte neamuri mai mari și mai puternice decât tine;"],[2,"și când Domnul Dumnezeul tău îi va da înaintea ta și îi vei lovi, atunci îi vei nimici cu desăvârșire. Să nu faci legământ cu ei și să nu ai milă de ei."],[3,"Să nu faci căsătorii cu ei. Să nu dai fiica ta fiului său și nici să nu o iei pe fiica lui pentru fiul tău."],[4,"Căci asta i-ar abate pe fiii tăi de la Mine, ca să slujească altor dumnezei. Deci mânia Domnului s-ar aprinde împotriva ta și te va nimici repede."],[5,"Dar să le purtați astfel: să le dărâmăți altarele, să le sfărâmați stâlpii, să le tăiați stâlpii din Așera și să le ardeți cu foc chipurile cioplite."],[6,"Căci tu ești un popor sfânt pentru Domnul Dumnezeul tău. Domnul Dumnezeul tău te-a ales ca să fii un popor pentru stăpânirea Lui, mai presus de toate popoarele care sunt pe fața pământului."],[7,"Domnul nu și-a pus dragostea asupra ta și nu te-a ales, pentru că erai mai mare decât orice popor; căci ai fost cel mai puțin dintre popoarele;"],[8,"dar pentru că Domnul te iubește și pentru că dorește să țină jurământul pe care l-a jurat părinților tăi, Domnul te-a scos cu o mână puternică și te-a răscumpărat din casa robiei, din mâna lui Faraon, împăratul Egiptului."],[9,"Să știi deci că Domnul Dumnezeul tău însuși este Dumnezeu, Dumnezeul credincios, care păzește legământul și bunătatea de o mie de neam cu cei ce-L iubesc și păzesc poruncile Lui,"],[10,"și răsplătește pe cei ce-L urăsc în față, ca să-i nimicească. El nu va fi lejer față de cel ce îl urăște. Îl va răsplăti în față."],[11,"Să păzești așadar poruncile, legile și rânduielile pe care ți le poruncesc astăzi, ca să le împlinești."],[12,"Pentru că veți asculta aceste porunci, le veți păzi și le împliniți, Domnul, Dumnezeul vostru, va păzi cu voi legământul și bunătatea pe care le-a jurat părinților voștri."],[13,"El te va iubi, te va binecuvânta și te va înmulți. El va binecuvânta, de asemenea, rodul trupului tău și rodul pământului tău, grâul tău, vinul tău nou și untdelemnul tău, sporul turmelor tale și puii turmei tale, în țara pe care a jurat părinților tăi că ți-o va da."],[14,"Vei fi binecuvântat mai presus de toate popoarele. Nu va fi bărbătesc sau femeie stearpă printre voi și nici printre vitele voastre."],[15,"Domnul va îndepărta de la tine toată boala; și nu va pune asupra voastră niciuna dintre bolile rele ale Egiptului, pe care le cunoașteți, ci le va pune asupra tuturor celor ce vă urăsc."],[16,"Vei mistui toate popoarele pe care ți le va da Domnul Dumnezeul tău. Ochiul tău să nu-i fie milă de ei. Să nu slujiți zeilor lor; căci asta ar fi o capcană pentru tine."],[17,"Dacă vei spune în inima ta: „Aceste neamuri sunt mai multe decât mine, cum le voi deposeda?”"],[18,"nu te vei teme de ei. Să-ți aduci aminte bine ce a făcut Domnul Dumnezeul tău lui Faraon și întregului Egipt:"],[19,"încercările mari pe care le-au văzut ochii tăi, semnele, minunile, mâna puternică și brațul întins, prin care te-a scos Domnul Dumnezeul tău. Așa va face Domnul Dumnezeul tău tuturor popoarelor de care te temi."],[20,"În plus, DOMNUL Dumnezeul tău va trimite viespe în mijlocul lor, până când cei care au rămas și se ascund, vor pieri dinaintea ta."],[21,"Nu te vei speria de ei; căci Domnul Dumnezeul tău este în mijlocul tău, un Dumnezeu mare și înfricoșător."],[22,"Domnul Dumnezeul tău va izgoni aceste neamuri dinaintea ta încetul cu încetul. Nu le puteți consuma deodată, ca nu cumva animalele câmpului să se înmulțească asupra voastră."],[23,"Dar Domnul, Dumnezeul tău, îi va da înaintea ta și îi va încurca cu o mare tulburare, până vor fi nimiciți."],[24,"El îi va da pe regii lor în mâinile tale și vei face să piară numele lor de sub cer. Nimeni nu va putea sta în fața ta până când nu-i vei distruge."],[25,"Vei arde cu foc imaginile gravate ale zeilor lor. Să nu poftești argintul sau aurul care este pe ele și să nu-l iei pentru tine, ca să nu fii prins în ele; căci este o urâciune pentru Domnul Dumnezeul tău."],[26,"Să nu aduci o urâciune în casa ta și să nu devii un lucru devotat ca acesta. Îl vei detesta cu desăvârșire. Îl vei urî cu totul; căci este un lucru devotat."]]],[8,[[1,"Veți avea grijă să împliniți toate poruncile pe care vi le poruncesc astăzi, ca să trăiți și să vă înmulțiți și să intrați și să stăpâniți țara pe care a jurat-o Domnul părinților voștri."],[2,"Să-ți aduci aminte de tot drumul pe care te-a condus Domnul Dumnezeul tău în acești patruzeci de ani în pustie, ca să te smerească, să te încerce, să știe ce este în inima ta, dacă vei păzi sau nu poruncile Lui."],[3,"El te-a smerit, ți-a îngăduit să fii flămând și te-a hrănit cu mană, pe care tu nu o cunoșteai, nici părinții tăi nu o cunoșteau, ca să te învețe că omul nu trăiește numai cu pâine, ci omul trăiește din orice cuvânt care iese din gura Domnului."],[4,"Hainele tale nu ți-au îmbătrânit și nici piciorul nu ți s-a umflat în acești patruzeci de ani."],[5,"Să vezi în inima ta că, așa cum omul își pedepsește fiul, așa te pedepsește Domnul Dumnezeul tău."],[6,"Să păzești poruncile Domnului Dumnezeului tău, să umbli pe căile Lui și să te temi de El."],[7,"Căci Domnul Dumnezeul tău te aduce într-o țară bună, o țară cu pâraie de apă, cu izvoare și cu ape subterane care curg în văi și dealuri;"],[8,"un pământ de grâu, orz, viță de vie, smochini și rodii; un pământ de măslini și miere;"],[9,"un pământ în care veți mânca pâine fără lipsă, să nu vă lipsească nimic din el; un pământ ale cărui pietre sunt fier și din ale cărui dealuri poți săpa aramă."],[10,"Vei mânca și vei fi săturat și vei binecuvânta pe Domnul Dumnezeul tău pentru pământul bun pe care ți-a dat-o."],[11,"Păziți-vă să nu uitați pe Domnul, Dumnezeul vostru, fără a păzi poruncile Lui, poruncile și legile Lui, pe care vi le poruncesc astăzi;"],[12,"ca nu cumva, când veţi mânca şi vă veţi sătura, şi veţi zidi case frumoase şi veţi locui în ele;"],[13,"şi când vi se vor înmulţi turmele şi oilele voastre, iar argintul şi aurul vostru se vor înmulţi şi tot ce aveţi se va înmulţi;"],[14,"atunci inima ta se va înălța și vei uita pe Domnul Dumnezeul tău, care te-a scos din țara Egiptului, din casa robiei;"],[15,"care te-a condus prin pustia mare și cumplită, cu șerpi veninoși și scorpioni și pământ însetat unde nu era apă; care a turnat apă pentru tine din stânca de silex;"],[16,"care te-a hrănit în pustie cu mană, pe care părinții tăi nu o cunoșteau, ca să te smerească și să te probeze, ca să-ți facă bine la sfârșitul tău;"],[17,"și ca să nu spui în inima ta: „Puterea și puterea mâinii mele mi-au adus această bogăție”."],[18,"Dar să-ți aduci aminte de Domnul, Dumnezeul tău, căci El este cel care îți dă putere să obții bogății, ca să-și îndeplinească legământul pe care l-a jurat părinților tăi, așa cum este astăzi."],[19,"Dacă vei uita pe Domnul, Dumnezeul tău, și vei merge după alți dumnezei, și le vei sluji și te vei închina, mărturisesc împotriva ta astăzi că vei pieri."],[20,"Precum neamurile pe care DOMNUL le face să piară înaintea ta, așa vei pieri, pentru că n-ai ascultat de glasul Domnului Dumnezeului tău."]]],[9,[[1,"Ascultă, Israel! Să treci astăzi Iordanul, să intri să deposedezi națiuni mai mari și mai puternice decât tine, cetăți mari și întărite până la cer,"],[2,"un popor mare și înalt, fiii anacilor, pe care îi cunoști și despre care ai auzit spunând: „Cine poate sta înaintea fiilor lui Anac?”"],[3,"Să știți deci astăzi că Domnul Dumnezeul vostru este Cel care trece înaintea voastră ca un foc mistuitor. El îi va nimici și îi va doborî înaintea ta. Deci să-i alungi și să-i faci să piară repede, precum ți-a spus Domnul."],[4,"Nu spune în inima ta, după ce Domnul Dumnezeul tău i-a alungat dinaintea ta: „Pentru dreptatea mea, Domnul m-a adus să stăpânesc țara aceasta”. pentru că Domnul îi alungă dinaintea ta din cauza răutăţii acestor neamuri."],[5,"Nu pentru dreptatea ta sau pentru dreptatea inimii tale intri să stăpânești țara lor; dar, pentru răutatea acestor neamuri, Domnul, Dumnezeul tău, le alungă dinaintea ta, ca să întărească cuvântul pe care Domnul l-a jurat părinţilor tăi, lui Avraam, Isaac şi Iacov."],[6,"Să știi deci că Domnul, Dumnezeul tău, nu îți dă stăpânirea acestei țări bune pentru dreptatea ta, căci ești un popor cu cerul înțepenit."],[7,"Adu-ți aminte și nu uita cum ai provocat la mânie pe Domnul Dumnezeul tău în pustie. Din ziua în care ai părăsit țara Egiptului și până ai ajuns în acest loc, ai fost răzvrătit împotriva Domnului."],[8,"De asemenea, în Horeb ai stârnit mânie pe Domnul, și Domnul S-a mâniat pe tine ca să te nimicească."],[9,"După ce m-am suit pe munte să primesc tablele de piatră, tablele legământului pe care l-a făcut Domnul cu voi, atunci am stat pe munte patruzeci de zile și patruzeci de nopți. Nici nu am mâncat pâine, nici nu am băut apă."],[10,"Domnul mi-a dat cele două table de piatră scrise cu degetul lui Dumnezeu. Peste ei erau toate cuvintele pe care le-a spus Domnul cu tine pe munte, din mijlocul focului, în ziua adunării."],[11,"La sfârşitul a patruzeci de zile şi patruzeci de nopţi, Domnul mi-a dat cele două table de piatră, chiar tablele legământului."],[12,"Domnul mi-a zis: „Scoală-te, coboară-te repede de aici, căci poporul tău, pe care l-ai scos din Egipt, s-a stricat, s-a abătut repede de la calea pe care le-am poruncit eu și și-au făcut un chip turnat!”"],[13,"Mai mult, Domnul mi-a vorbit, zicând: „Am văzut poporul acesta și iată, ei sunt un popor cu gâtul înțepenit."],[14,"Lasă-mă în pace, ca să-i nimicesc și să le șterg numele de sub cer; și voi face din tine un neam mai puternic și mai mare decât ei.”"],[15,"Așa că m-am întors și m-am coborât de pe munte și muntele ardea de foc. Cele două table ale legământului erau în cele două mâini ale mele."],[16,"M-am uitat și iată că ai păcătuit împotriva Domnului Dumnezeului tău. v-ați făcut un vițel mulat. Te-ai abătut repede de la calea pe care ți-a poruncit Domnul."],[17,"Am luat cele două tăblițe și le-am aruncat din mâinile mele și le-am rupt sub ochii tăi."],[18,"Am căzut înaintea Domnului, ca la început, patruzeci de zile și patruzeci de nopți. Nici nu am mâncat pâine, nici nu am băut apă, din pricina tuturor păcatului tău pe care l-ai păcătuit, făcând ceea ce este rău înaintea Domnului, ca să-l provoace la mânie."],[19,"Căci m-am temut de mânia și de nemulțumirea fierbinte cu care s-a mâniat Domnul împotriva ta, ca să te nimicească. Dar Domnul m-a ascultat și atunci."],[20,"Domnul a fost destul de supărat pe Aaron pentru a-l nimici. M-am rugat și pentru Aaron în același timp."],[21,"Am luat păcatul tău, vițelul pe care l-ai făcut, l-am ars cu foc și l-am zdrobit, măcinat-o foarte mic, până a devenit fin ca praful. I-am aruncat praful în pârâul care cobora din munte."],[22,"La Tabera, la Masa și la Chibrot Hataava, ați provocat la mânie pe Domnul."],[23,"Când Domnul te-a trimis din Cades Barnea, zicând: „Suie-te și stăpânește țara pe care ți-am dat-o”, te-ai răzvrătit împotriva poruncii Domnului Dumnezeului tău și nu l-ai crezut și nu i-ai ascultat glasul."],[24,"Ai fost răzvrătit împotriva Domnului din ziua în care te-am cunoscut."],[25,"Așa că am căzut înaintea Domnului în cele patruzeci de zile și patruzeci de nopți în care am căzut, pentru că Domnul spusese că te va nimici."],[26,"M-am rugat Domnului și am zis: „Doamne, Doamne, nu-ți nimici poporul și moștenirea pe care ai răscumpărat-o prin măreția Ta și pe care ai scos-o din Egipt cu mână puternică."],[27,"Adu-ți aminte de slujitorii tăi, Avraam, Isaac și Iacov. Nu te uita la încăpățânarea acestui popor, nici la răutatea lui, nici la păcatul lui,"],[28,"ca nu cumva țara din care ne-ai scos să zică: „Pentru că Domnul nu a putut să-i aducă în țara pe care le-a făgăduit, și pentru că i-a urât, i-a scos să-i omoare în pustie”."],[29,"Dar ei sunt poporul tău și moștenirea ta, pe care i-ai scos cu puterea ta mare și cu brațul tău întins.”"]]],[10,[[1,"În vremea aceea, Domnul mi-a zis: „Tăiați două table de piatră ca primele și urcă-te la Mine pe munte și fă un chivot de lemn."],[2,"Voi scrie pe table cuvintele care au fost pe primele table pe care le-ai spart și le vei pune în corabie.”"],[3,"Am făcut deci un chivot din lemn de salcâm, am tăiat două table de piatră ca prima și m-am suit pe munte, având cele două table în mână."],[4,"El a scris pe table, după prima scriere, cele zece porunci, pe care ți le-a spus Domnul pe munte, din mijlocul focului, în ziua adunării; şi mi le-a dat Domnul."],[5,"M-am întors și m-am coborât de pe munte și am pus tablele în chivotul pe care îl făcusem; și acolo sunt așa cum mi-a poruncit Domnul."],[6,"(Copiii lui Israel au plecat de la Beerot Bene Iaakan la Moserah. Acolo a murit Aaron și acolo a fost îngropat; și fiul său Eleazar a slujit preot în locul lui."],[7,"De acolo au călătorit la Gudgodah; și de la Gudgoda până la Iotbata, o țară cu pâraie de apă."],[8,"În vremea aceea, Domnul a pus deoparte seminția lui Levi să poarte chivotul legământului Domnului, să stea înaintea Domnului, ca să-i slujească și să binecuvânteze în Numele Lui, până astăzi."],[9,"De aceea Levi nu are nicio parte și nici o moștenire cu frații săi; Domnul este moștenirea lui, după cum i-a spus Domnul Dumnezeul tău.)"],[10,"Am stat pe munte, ca la prima dată, patruzeci de zile și patruzeci de nopți; și Domnul m-a ascultat și în acea dată. Domnul nu te-ar distruge."],[11,"Domnul mi-a zis: „Scoală-te, pornește-ți înaintea poporului; și ei vor intra și vor stăpâni țara pe care am jurat părinților lor că le-o dau.”"],[12,"Acum, Israele, ce cere de la tine Domnul Dumnezeul tău, decât să te temi de Domnul Dumnezeul tău, să umbli în toate căile Lui, să-l iubești și să slujești Domnului Dumnezeului tău din toată inima ta și din tot sufletul tău,"],[13,"să păzești poruncile și legile Domnului, pe care ți le poruncesc astăzi pentru binele tău?"],[14,"Iată, al DOMNULUI Dumnezeul tău este cerul, cerul cerurilor și pământul, cu tot ce este în el."],[15,"Numai DOMNUL a avut plăcere în părinții tăi să-i iubească și a ales sămânța lor după ei, pe tine mai presus de toate popoarele, așa cum este astăzi."],[16,"Tăiește împrejur deci prepuțul inimii tale și nu mai fii cu gâtul înțepenit."],[17,"Căci Domnul, Dumnezeul tău, este Dumnezeul zeilor și Domnul domnilor, Dumnezeul cel mare, cel puternic și cel înfricoșător, care nu respectă oamenii și nu ia mită."],[18,"El face dreptate orfanului și văduvei și iubește pe străin dându-i mâncare și îmbrăcăminte."],[19,"De aceea iubiți pe străin, căci ați fost străini în țara Egiptului."],[20,"Să te temi de Domnul Dumnezeul tău. Îi vei sluji. Te vei lipi de el și vei jura pe numele lui."],[21,"El este lauda ta și el este Dumnezeul tău, care a făcut pentru tine aceste lucruri mari și înfricoșătoare pe care le-au văzut ochii tăi."],[22,"Părinţii voştri s-au pogorât în ​​Egipt cu şaptezeci de persoane; și acum Domnul Dumnezeul tău te-a făcut ca stelele cerului în mulțime."]]],[11,[[1,"De aceea să iubești pe Domnul Dumnezeul tău și să păzești întotdeauna poruncile Lui, legile, poruncile și poruncile Lui."],[2,"Cunoașteți astăzi, căci nu vorbesc cu copiii voștri care nu au cunoscut și care n-au văzut pedeapsa Domnului Dumnezeului vostru, măreția Lui, mâna Lui puternică, brațul Lui întins,"],[3,"semnele și lucrările lui, pe care le-a făcut în mijlocul Egiptului lui Faraon, împăratul Egiptului, și întregii sale țări;"],[4,"și ce a făcut el armatei Egiptului, cailor și carelor lor; cum a făcut să se reverse apa Mării Roșii, când te urmăreau pe tine și cum Domnul i-a nimicit până în ziua de azi;"],[5,"și ce ți-a făcut el în pustie până când ai ajuns în locul acesta;"],[6,"și ce le-a făcut lui Datan și lui Abiram, fiii lui Eliab, fiul lui Ruben, cum și-a deschis pământul gura și i-a înghițit, împreună cu casele lor, cu corturile lor și cu orice ființă care i-a urmat, în mijlocul întregului Israel;"],[7,"dar ochii tăi au văzut toată lucrarea mare a Domnului pe care a făcut-o."],[8,"De aceea, să păzești toată porunca pe care ți-o poruncesc astăzi, ca să fii puternic și să intri și să stăpânești țara pe care o vei stăpâni;"],[9,"și să vă prelungiți zilele în țara pe care DOMNUL a jurat părinților voștri că o va da lor și semințelor lor, o țară în care curge lapte și miere."],[10,"Căci țara în care intri să stăpânești nu este ca țara Egiptului din care ai ieșit, unde ți-ai semănat sămânța și ai udat-o cu piciorul, ca o grădină de ierburi;"],[11,"dar țara pe care o vei stăpâni este o țară de dealuri și văi, care bea apă din ploaia cerului,"],[12,"o ţară de care are grijă DOMNUL Dumnezeul tău. Ochii Domnului Dumnezeului tău sunt mereu ațintiți asupra ei, de la începutul anului până la sfârșitul anului."],[13,"Se va întâmpla dacă vei asculta cu sârguință de poruncile Mele pe care ți le poruncesc astăzi, să iubești pe Domnul Dumnezeul tău și să-I slujești din toată inima ta și din tot sufletul tău,"],[14,"că voi da ploaia pentru țara voastră la vremea lui, ploaia devreme și ploaia târzie, ca să vă strângeți grânele, vinul vostru nou și untdelemnul vostru."],[15,"Voi da iarbă în câmpurile voastre pentru vitele voastre și veți mânca și veți fi săturați."],[16,"Fii atent, ca nu cumva inima ta să se înşele şi să te întorci ca să slujeşti altor dumnezei şi să te închini lor;"],[17,"și mânia Domnului să se aprindă împotriva voastră și a închis cerul, ca să nu mai fie ploaie și țara să nu-și dea roadele; şi vei pieri repede din ţara bună pe care ţi-o dă Domnul."],[18,"De aceea, vei pune aceste cuvinte ale mele în inima ta și în sufletul tău. Le vei lega ca semn pe mâna ta, iar ele vor fi ca frunte între ochi."],[19,"Le vei învăța copiilor tăi, vorbind despre ei când vei sta în casa ta, când vei merge pe drum, când te culci și când te scoli."],[20,"Le vei scrie pe stâlpii casei tale și pe porțile tale;"],[21,"pentru ca zilele voastre și ale copiilor voștri să se înmulțească în țara pe care Domnul a jurat părinților voștri că le va da, ca zilele cerurilor deasupra pământului."],[22,"Căci dacă vei păzi cu sârguință toate aceste porunci pe care ți le poruncesc, să le împlinești, să iubești pe Domnul Dumnezeul tău, să umbli în toate căile Lui și să te agăți de el,"],[23,"atunci Domnul va izgoni toate aceste neamuri dinaintea voastră și veți izgoni națiuni mai mari și mai puternice decât voi înșivă."],[24,"Orice loc pe care calcă talpa piciorului tău va fi al tău: din pustie și Liban, de la râu, râul Eufrat, până la marea de apus, va fi hotarul tău."],[25,"Niciun bărbat nu va putea sta în fața ta. Domnul, Dumnezeul tău, va pune frica de tine și frica față de tine peste toată țara pe care vei călca, așa cum ți-a spus El."],[26,"Iată, vă pun astăzi înainte o binecuvântare și un blestem:"],[27,"binecuvântarea, dacă asculți de poruncile Domnului Dumnezeului tău, pe care ți le poruncesc astăzi;"],[28,"și blestemul, dacă nu vei asculta de poruncile Domnului Dumnezeului tău, ci te abate de la calea pe care ți-o poruncesc astăzi, ca să mergi după alți dumnezei pe care nu i-ai cunoscut."],[29,"Când Domnul Dumnezeul tău te va aduce în țara pe care mergi să o stăpânești, vei pune binecuvântarea pe muntele Garizim și blestemul pe muntele Ebal."],[30,"Nu sunt ei dincolo de Iordan, în spatele drumului spre apusul soarelui, în țara canaaniților care locuiesc în Araba, lângă Ghilgal, lângă stejarii din More?"],[31,"Căci vei trece Iordanul ca să intri să stăpânești țara pe care ți-o dă Domnul, Dumnezeul tău, și o vei stăpâni și vei locui în ea."],[32,"Să păziți să împliniți toate legile și rânduielile pe care vi le pun astăzi înaintea voastră."]]],[12,[[1,"Acestea sunt legile și rânduielile pe care să le împliniți pentru a le împlini în țara pe care ți-a dat-o Domnul, Dumnezeul părinților tăi, ca să stăpânești în toate zilele pe care le vei trăi pe pământ."],[2,"Vei nimici cu siguranță toate locurile în care neamurile pe care le vei izgoni și-au slujit dumnezeilor lor: pe munții înalți și pe dealuri și sub orice copac verde."],[3,"Le vei dărâma altarele, le vei sfărâma stâlpii și le vei arde cu foc stâlpii din Așera. Vei tăia imaginile gravate ale zeilor lor. Vei nimici numele lor din acel loc."],[4,"Să nu faci așa Domnului Dumnezeului tău."],[5,"Dar în locul pe care Domnul Dumnezeul tău îl va alege dintre toate semințiile tale, ca să-și pună acolo numele, să-i cauți locuința și vei veni acolo."],[6,"Să aduci acolo arderile tale de tot, jertfele tale, zecimiile tale, jertfa legănată a mâinii tale, jurămintele tale, darurile tale libere și întâiul născut din turma ta și din turma ta."],[7,"Acolo veți mânca înaintea DOMNULUI Dumnezeul vostru și vă veți bucura de tot ceea ce vă puneți mâna, voi și casele voastre, prin care v-a binecuvântat Domnul Dumnezeul vostru."],[8,"Să nu faceți toate lucrurile pe care le facem noi astăzi aici, fiecare om ce este drept în ochii lui;"],[9,"căci încă nu ai ajuns la restul și la moștenirea pe care ți-o dă Domnul, Dumnezeul tău."],[10,"Dar când vei trece Iordanul și vei locui în țara pe care DOMNUL Dumnezeul tău ți-o dă moștenire și el te va odihni de toți vrăjmașii tăi din jurul tău, astfel încât să locuiești în siguranță,"],[11,"atunci se va întâmpla ca în locul pe care îl va alege Domnul, Dumnezeul tău, pentru a face să locuiască acolo numele Lui, acolo să aduci tot ce îți poruncesc: arderile tale de tot, jertfele tale, zecimii tale, darul legănat al mâinii tale și toate jurămintele tale alese, pe care le faci Domnului."],[12,"Să te bucuri înaintea Domnului, Dumnezeului tău, tu și fiii tăi, fiicele tale, slujitorii tăi, robii tale și levitul care este în porțile tale, pentru că nu are parte și nici moștenire cu tine."],[13,"Aveți grijă să nu vă aduceți arderile de tot în orice loc pe care îl vedeți;"],[14,"dar în locul pe care l-a ales Domnul într-una din semințiile tale, acolo să-ți aduci arderi de tot și acolo să faci tot ce-ți poruncesc."],[15,"Totuși, poți să ucizi și să mănânci carne în toate porțile tale, după toată dorința sufletului tău, după binecuvântarea Domnului, Dumnezeului tău, pe care ți-a dat-o. Cei necurați și cei curați pot să mănânce din ea, ca și din gazelă și căprioară."],[16,"Numai tu să nu mănânci sângele. Îl vei turna pe pământ ca apa."],[17,"Să nu mănânci în interiorul porților tale zecimea din grânul tău, sau din vinul tău nou, sau din untdelemnul tău, sau întâiul născut din turma ta sau din turma ta, nici din jurămintele tale pe care le faci, nici jertfele tale de bunăvoie, nici jertfa legănată a mâinii tale;"],[18,"ci să le mănânci înaintea Domnului, Dumnezeului tău, în locul pe care îl va alege Domnul, Dumnezeul tău: tu, fiul tău, fiica ta, robul tău, roaba ta și levitul care este la porțile tale. Te vei bucura înaintea Domnului, Dumnezeului tău, în tot ceea ce ai pus mâna ta."],[19,"Ai grijă să nu părăsești levitul atâta timp cât locuiești în țara ta."],[20,"Când Domnul, Dumnezeul tău, îți lărgește hotarul, așa cum ți-a promis, și vei zice: „Vreau să mănânc carne”, pentru că sufletul tău vrea să mănânce carne, vei putea mânca carne, după toate poftele sufletului tău."],[21,"Dacă locul pe care îl va alege Domnul Dumnezeul tău pentru a-și pune numele este prea departe de tine, atunci să-ți ucizi cireada și oile tale, pe care ți le-a dat Domnul, așa cum ți-am poruncit; și poți mânca în interiorul porților tale, după toată dorința sufletului tău."],[22,"Așa cum se mănâncă gazela și căprioara, așa vei mânca din ea. Cel necurat și cel curat pot mânca din ea deopotrivă."],[23,"Asigurați-vă doar că nu mâncați sânge; căci sângele este viața. Să nu mănânci viața cu carnea."],[24,"Să nu-l mănânci. Îl vei turna pe pământ ca apa."],[25,"Să nu mănânci din ea, ca să-ți fie bine ție și copiilor tăi după tine, când vei face ceea ce este drept în ochii Domnului."],[26,"Numai lucrurile tale sfinte pe care le ai și jurămintele tale să le iei și să mergi la locul pe care-l va alege Domnul."],[27,"Să aduci arderile tale de tot, carnea și sângele, pe altarul Domnului Dumnezeului tău. Sângele jertfelor tale să fie turnat pe altarul Domnului Dumnezeului tău și să mănânci carnea."],[28,"Păzește și ascultă toate aceste cuvinte pe care ți le poruncesc, ca să-ți fie bine ție și copiilor tăi după tine în veci, când vei face ceea ce este bine și drept în ochii Domnului, Dumnezeului tău."],[29,"Când DOMNUL Dumnezeul tău va nimici neamurile dinaintea ta, unde vei intra ca să le izgonești, și le vei izgoni și vei locui în țara lor,"],[30,"ai grijă să nu fii prins să-i urmezi după ce vor fi nimiciți dinaintea ta și să nu întrebi după dumnezeii lor, zicând: „Cum slujesc aceste neamuri zeilor lor? Eu voi face la fel.”"],[31,"Să nu faci aşa Domnului Dumnezeului tău; pentru că toate urâciunile aduse Domnului, pe care el o urăsc, au făcut dumnezeilor lor; pentru că și-au ard chiar fiii și fiicele în foc pentru zeii lor."],[32,"Orice lucru vă poruncesc, să păziți să faceți. Să nu adaugi la el, nici să nu iei din el."]]],[13,[[1,"Dacă se ridică printre voi un profet sau un visător de vise și vă dă un semn sau o minune,"],[2,"și se împlinește semnul sau minunea despre care ți-a vorbit, zicând: „Să mergem după alți dumnezei” (pe care nu i-ați cunoscut) „și să le slujim”."],[3,"nu vei asculta cuvintele acelui profet sau acelui visător de vise; căci Domnul Dumnezeul tău te pune la încercare, ca să știi dacă iubești pe Domnul Dumnezeul tău din toată inima ta și din tot sufletul tău."],[4,"Să umbli după Domnul Dumnezeul tău, să te temi de El, să păzești poruncile Lui și să asculți de glasul Lui. Să-l slujești și să te agăți de el."],[5,"Acel profet, sau acel visător de vise, va fi pedepsit cu moartea, pentru că a vorbit răzvrătire împotriva Domnului, Dumnezeului tău, care te-a scos din țara Egiptului și te-a răscumpărat din casa robiei, ca să te scoată de la calea pe care ți-a poruncit să mergi Domnul Dumnezeul tău. Astfel vei îndepărta răul din mijlocul tău."],[6,"Dacă fratele tău, fiul mamei tale, sau fiul tău, sau fiica ta, sau soția sânului tău, sau prietenul tău care este ca sufletul tău, te ademenește pe ascuns, zicând: „Să mergem să slujim altor dumnezei” – pe care nu i-ai cunoscut nici tu, nici părinților tăi;"],[7,"a zeilor popoarelor care sunt în jurul tău, aproape de tine sau departe de tine, de la un capăt al pământului până la celălalt capăt al pământului,"],[8,"nu-l vei fi de acord și nici nu-l vei asculta; nici ochiul tău nu-l va milă de el, nici nu-l vei cruţa, nici nu-l vei ascunde;"],[9,"dar cu siguranță îl vei ucide. Mâna ta să fie mai întâi asupra lui, ca să-l omoare, și apoi mâinile întregului popor."],[10,"Să-l ucizi cu pietre până la moarte, pentru că a căutat să te îndepărteze de Domnul Dumnezeul tău, care te-a scos din țara Egiptului, din casa robiei."],[11,"Tot Israelul va asculta și se va teme și nu va mai face vreo răutate ca aceasta între voi."],[12,"Dacă auzi despre una din cetățile tale, pe care ți-o dă Domnul Dumnezeul tău să locuiești acolo, asta"],[13,"niște oameni răi au ieșit din mijlocul tău și au atras locuitorii orașului lor, zicând: „Să mergem să slujim altor dumnezei”, pe care nu i-ați cunoscut,"],[14,"atunci vei cerceta, cerceta și cere cu sârguință. Iată, dacă este adevărat și lucru cert că s-a făcut o asemenea urâciune între voi,"],[15,"vei lovi cu ascuțișul sabiei pe locuitorii acelei cetăți, cu ascuțișul sabiei, cu tot ce este în ea și cu vitele ei."],[16,"Să strângi tot prada ei în mijlocul străzii ei și să arzi cu foc cetatea, cu tot prada ei, înaintea Domnului Dumnezeului tău. Va fi o grămadă pentru totdeauna. Nu va fi construit din nou."],[17,"Nimic din ceea ce este devotat nu se va lipi de mâna ta, pentru ca Domnul să se întoarcă de la aprinsul mâniei Sale și să-ți facă milă, să aibă milă de tine și să te înmulțească, așa cum a jurat părinților tăi,"],[18,"când asculți glasul Domnului Dumnezeului tău, ca să păzești toate poruncile Lui, pe care ți le poruncesc astăzi, să faci ce este drept în ochii Domnului Dumnezeului tău."]]],[14,[[1,"Voi sunteți copiii Domnului Dumnezeului vostru. Să nu vă tăiați și să nu faceți nicio chelie între ochi pentru morți."],[2,"Căci ești un popor sfânt pentru Domnul, Dumnezeul tău, și Domnul te-a ales ca să fii un popor pentru stăpânirea Sa, mai presus de toate popoarele care sunt pe fața pământului."],[3,"Să nu mănânci nimic abominabil."],[4,"Acestea sunt animalele pe care le puteți mânca: boul, oaia, capra,"],[5,"căprioara, gazela, căpriorul, capra sălbatică, ibexul, antilopa și capra."],[6,"Orice animal care desparte copita și care are copita despicată în două și rumegă, puteți mânca dintre animale."],[7,"Totuși, pe aceștia să nu mănânci din cei care rumecă sau din cei care au copita despicată: cămila, iepurele și iepurele. Pentru că rumea, dar nu desface copita, sunt necurate pentru tine."],[8,"Porcul, pentru că are copita despicată, dar nu rumea, este necurat pentru tine. Să nu mâncați carnea lor. Să nu atingeți cadavrele lor."],[9,"Pe acestea le puteți mânca din tot ce este în ape: puteți mânca tot ce are aripioare și solzi."],[10,"Să nu mănânci ce nu are aripioare și solzi. Este necurat pentru tine."],[11,"Dintre toate păsările curate pe care le puteți mânca."],[12,"Dar acestea sunt acelea din care nu veți mânca: vulturul, vulturul, ospreatorul,"],[13,"zmeul roșu, șoimul, zmeul de orice fel,"],[14,"fiecare corb de orice fel,"],[15,"struțul, bufnița, pescărușul, șoimul de orice fel,"],[16,"bufnița mică, bufnița mare, bufnița cu coarne,"],[17,"pelicanul, vulturul, cormoranul,"],[18,"barza, stârcul după felul său, hupa și liliacul."],[19,"Toate târâtoarele înaripate sunt necurate pentru tine. Ele nu vor fi mâncate."],[20,"Dintre toate păsările curate pe care le puteți mânca."],[21,"Să nu mâncați din nimic care moare de la sine. Poți să-l dai străinului care locuiește printre tine și care este în porțile tale, ca să-l mănânce; sau îl puteți vinde unui străin; căci tu ești un popor sfânt pentru Domnul Dumnezeul tău."],[22,"Cu siguranță vei da zeciuială tot sporul seminței tale, care iese din câmp, an de an."],[23,"Să mănânci înaintea DOMNULUI Dumnezeul tău, în locul pe care El l-a ales ca să locuiască Numele Lui, zecimea de grâne, din vinul tău nou, din untdelemnul tău și din întâiul născut din turma ta și din turma ta; ca să înveți să te temi mereu de Domnul Dumnezeul tău."],[24,"Dacă drumul este prea lung pentru tine, încât nu poți să îl duci, pentru că locul pe care Domnul Dumnezeul tău îl va alege pentru a-și pune acolo numele este prea departe de tine, când te va binecuvânta Domnul Dumnezeul tău,"],[25,"apoi îl vei preface în bani, vei lega banii în mâna ta și vei merge la locul pe care îl va alege Domnul Dumnezeul tău."],[26,"Să schimbi banii pentru orice dorește sufletul tău: pentru vite, sau pentru oi, sau pentru vin, sau pentru băutură tare, sau pentru orice îți cere sufletul tău. Să mănânci acolo înaintea Domnului Dumnezeului tău și să te bucuri, tu și casa ta."],[27,"Să nu părăsești pe levitul care este în porțile tale, căci nu are parte și nici moștenire cu tine."],[28,"La sfârșitul fiecărui trei ani, să aduci toată zecimea din sporul tău în același an și să o depozitezi la porțile tale."],[29,"Levitul, pentru că nu are parte și moștenire cu tine, precum și străinul care locuiește printre tine, orfanul și văduva care este în porțile tale, vor veni și vor mânca și se vor sătura; ca Domnul Dumnezeul tău să te binecuvânteze în toată lucrarea mâinii tale pe care o faci."]]],[15,[[1,"La sfârșitul fiecărui șapte ani, vei anula datoriile."],[2,"Acesta este modul în care se va proceda: fiecare creditor va elibera aproapele pe care a împrumutat-o. Nu va cere plată de la aproapele său și de la fratele său, pentru că s-a vestit eliberarea Domnului."],[3,"De la un străin poți să-l ceri; dar orice este al tău cu fratele tău, mâna ta va elibera."],[4,"Totuși, nu va fi sărac cu tine (căci Domnul te va binecuvânta cu siguranță în țara pe care ți-o dă ca moștenire DOMNUL Dumnezeul tău)"],[5,"dacă ai asculta cu sârguință de glasul Domnului Dumnezeului tău, ca să păzești să împlinești toată această poruncă pe care ți-o dau astăzi."],[6,"Căci Domnul Dumnezeul tău te va binecuvânta, așa cum ți-a promis. Vei împrumuta multor neamuri, dar nu vei împrumuta. Vei stăpâni peste multe neamuri, dar ele nu vor stăpâni peste tine."],[7,"Dacă un om sărac, unul dintre frații tăi, este cu tine în vreuna din porțile tale, în țara pe care ți-o dă Domnul, Dumnezeul tău, să nu-ți împietriști inima și să nu-ți închizi mâna de la fratele tău sărac;"],[8,"dar să-i deschizi cu siguranță mâna și să-i împrumuți suficient pentru nevoile lui, care îi lipsesc."],[9,"Ferește-te să nu fie un gând rău în inima ta, care să zică: „Al șaptelea an, anul eliberării, este aproape”, și ochiul tău să fie rău împotriva fratelui tău sărac și să nu-i dai nimic; și el a strigat către DOMNUL împotriva ta și este păcat pentru tine."],[10,"Să dăruiești cu siguranță și inima ta nu se va întrista când îi vei da, pentru că pentru acest lucru te va binecuvânta Domnul Dumnezeul tău în toată lucrarea ta și în tot ceea ce ai pus mâna ta."],[11,"Căci săracii nu vor înceta niciodată să iasă din pământ. De aceea îți poruncesc să-ți deschizi mâna fratelui tău, nevoiașii și săracii tăi din țara ta."],[12,"Dacă fratele tău, un bărbat evreu sau o femeie evreică, ți se vinde și îți slujește șase ani, atunci în al șaptelea an să-l eliberezi de la tine."],[13,"Când îl lași să plece de la tine, să nu-l lași să plece gol."],[14,"Îi vei da din turma ta, din aria ta și din teascul tău de vin. După cum te-a binecuvântat Domnul Dumnezeul tău, să-i dai lui."],[15,"Să-ți aduci aminte că ai fost rob în țara Egiptului și că Domnul Dumnezeul tău te-a răscumpărat. De aceea vă poruncesc acest lucru astăzi."],[16,"Se va întâmpla dacă îți va spune: „Nu voi ieși de la tine”, pentru că te iubește pe tine și casa ta, pentru că îi este bine cu tine,"],[17,"atunci să iei o pungă și să i-o înfii prin urechea până la uşă, și el va fi slujitorul tău pentru totdeauna. De asemenea, slujitoarei tale să faci la fel."],[18,"Nu ți se va părea greu să-l lași să plece de la tine, pentru că a fost dublu față de valoarea unui angajat când te-a slujit șase ani. Domnul Dumnezeul tău te va binecuvânta în tot ceea ce faci."],[19,"Să-i închinați Domnului, Dumnezeului vostru, pe toți primii născuți bărbați care sunt născuți din turma voastră și din turma voastră. Să nu faci nicio lucrare cu întâiul născut al turmei tale, nici să-l tunzi pe întâiul născut al turmei tale."],[20,"Să mănânci din ea înaintea Domnului, Dumnezeului tău, an de an, în locul pe care îl va alege Domnul, tu și casa ta."],[21,"Dacă are vreun defect, dacă este șchiop sau orb, sau are vreun defect, să nu-l jertfiți Domnului Dumnezeului vostru."],[22,"Îl vei mânca la porțile tale. Cel necurat și cel curat îl vor mânca deopotrivă, ca gazela și ca cerbul."],[23,"Numai să nu-i mâncați sângele. Îl vei turna pe pământ ca apa."]]],[16,[[1,"Păzește luna Abib și prăznuiește Paștele Domnului Dumnezeului tău; căci în luna lui Abib, Domnul Dumnezeul tău te-a scos noaptea din Egipt."],[2,"Să jertfești Paștele Domnului, Dumnezeului tău, din turme și boi, în locul pe care Domnul îl va alege ca să-și facă numele să locuiască acolo."],[3,"Să nu mâncați pâine dospită cu ea. Să mănânci cu ea azime șapte zile, chiar pâinea necazului (căci ai ieșit în grabă din țara Egiptului), ca să-ți aduci aminte de ziua când ai ieșit din țara Egiptului în toate zilele vieții tale."],[4,"Nicio drojdie nu se va vedea la tine în toate hotarele tale, timp de șapte zile; Nici unul din carnea pe care o jertfiți în prima zi seara nu va rămâne toată noaptea până dimineața."],[5,"Să nu jertfeşti Paştele în nici una din porţile tale pe care ţi le dă Domnul Dumnezeul tău;"],[6,"dar în locul pe care îl va alege Domnul Dumnezeul tău, ca să facă să locuiască Numele Lui, acolo să jertfeşti Paştele seara, la apusul soarelui, la vremea când ai ieşit din Egipt."],[7,"Să o prăjiți și să o mâncați în locul pe care-l va alege Domnul, Dumnezeul vostru. Dimineața te vei întoarce la corturile tale."],[8,"Șase zile să mănânci azime. În ziua a șaptea să fie o adunare solemnă pentru Domnul Dumnezeul tău. Nu vei lucra."],[9,"Veți număra pentru voi înșivă șapte săptămâni. Din momentul în care începi să pui secera până la grânul în picioare, vei începe să numeri șapte săptămâni."],[10,"Să prăznuiești sărbătoarea săptămânilor Domnului, Dumnezeului tău, cu un dau de dar de bunăvoie din mâinile tale, pe care să-l dai după cum te va binecuvânta Domnul Dumnezeul tău."],[11,"Să te bucuri înaintea Domnului, Dumnezeului tău: tu, fiul tău, fiica ta, robul tău, roaba ta, levitul care este în porțile tale, străinul, orfanul și văduva care sunt printre tine, în locul pe care Domnul Dumnezeul tău îl va alege pentru a-i face să locuiască acolo numele."],[12,"Îți vei aminti că ai fost sclav în Egipt. Să păziți și să împliniți aceste legi."],[13,"Să prăznuiești sărbătoarea cortului șapte zile, după ce te vei strânge din aria ta și din teascul tău de vin."],[14,"Să te bucuri de sărbătoarea ta, tu, fiul tău, fiica ta, slujitorul tău, sluga ta, levitul, străinul, orfanul și văduva care stă în porțile tale."],[15,"Să prăznuiești o sărbătoare în cinstea Domnului, Dumnezeului tău, timp de șapte zile, în locul pe care l-a ales Domnul, pentru că Domnul, Dumnezeul tău, te va binecuvânta în tot sporul tău și în toată lucrarea mâinilor tale și te vei bucura cu totul."],[16,"De trei ori pe an, toți bărbații tăi să se înfățișeze înaintea Domnului Dumnezeului tău, în locul pe care-l va alege: la sărbătoarea azimelor, la sărbătoarea săptămânilor și la sărbătoarea cortului. Nu se vor înfățișa înaintea Domnului cu gol."],[17,"Fiecare om să dea după cum poate, după binecuvântarea Domnului, Dumnezeului vostru, pe care v-a dat-o."],[18,"Să faci judecători și dregători în toate porțile tale, pe care ți le dă Domnul Dumnezeul tău, după semințiile tale; și vor judeca poporul cu dreptate."],[19,"Să nu stric dreptatea. Nu trebuie să arătați parțialitate. Să nu iei mită, căci mită orbește ochii celor înțelepți și strica cuvintele celor drepți."],[20,"Vei urma ceea ce este cu totul drept, ca să trăiești și să moșteni țara pe care ți-o dă Domnul, Dumnezeul tău."],[21,"Să nu sădiți pentru voi înșivă o Așera din niciun fel de copac lângă altarul Domnului Dumnezeului vostru, pe care să-l faceți pentru voi."],[22,"Nici să nu ridici o piatră sfântă pe care Domnul, Dumnezeul tău, o urăște."]]],[17,[[1,"Să nu jertfii Domnului, Dumnezeului tău, un bou sau o oaie care să aibă vreo defecte sau ceva rău; căci aceasta este o urâciune pentru Domnul Dumnezeul tău."],[2,"Dacă se găsește printre voi, în oricare dintre porțile voastre pe care ți le dă Domnul, Dumnezeul tău, un bărbat sau o femeie care săvârșească ceea ce este rău înaintea Domnului Dumnezeului tău, călcându-și legământul,"],[3,"și s-a dus și s-a slujit altor dumnezei și s-a închinat lor sau soarelui, sau lunii sau vreuneia dintre stelele cerului, pe care nu le-am poruncit,"],[4,"și ți se spune și ai auzit despre asta, atunci vei cerceta cu sârguință. Iată, dacă este adevărat și este cert că o asemenea urâciune se face în Israel,"],[5,"atunci să scoți la porțile tale bărbatul sau femeia aceea care a făcut acest lucru rău, chiar și acel bărbat sau aceeași femeie; și îi vei ucide cu pietre până la moarte."],[6,"Din gura a doi martori sau a trei martori, cel ce va muri va fi pedepsit cu moartea. Din gura unui singur martor, el nu va fi pedepsit cu moartea."],[7,"Mâinile martorilor vor fi mai întâi asupra lui, ca să-l omoare, iar apoi mâinile întregului popor. Deci vei îndepărta răul din mijlocul tău."],[8,"Dacă se va ridica o chestiune prea grea pentru tine în judecată, între sânge și sânge, între pledoarie și pledoarie, și între lovitură și lovitură, fiind lucruri de controversă în interiorul porților tale, atunci să te ridici și să te sui la locul pe care-l va alege Domnul, Dumnezeul tău."],[9,"Să te duci la preoții care sunt leviți și la judecătorul care va fi în acele zile. Vei întreba și ei îți vor da verdictul."],[10,"Să faci după hotărârile hotărârii pe care ți-o vor da din locul pe care-l va alege Domnul. Vei avea grijă să faci după tot ce te vor învăța ei."],[11,"După hotărârile legii pe care te vor învăța ei și după judecata pe care ți-o vor spune, vei face. Să nu te îndepărtezi de la sentința pe care ți-o anunță, nici la dreapta, nici la stânga."],[12,"Omul care face cu îndrăzneală neascultând de preotul care stă să slujească acolo înaintea Domnului Dumnezeului tău sau de judecător, chiar acel om va muri. Vei îndepărta răul din Israel."],[13,"Tot poporul va auzi și se va teme și nu va mai face cu îngâmfare."],[14,"Când vei ajunge în țara pe care ți-o dă Domnul, Dumnezeul tău, și vei stăpâni pe ea și vei locui în ea și vei spune: „Voi pune peste mine un rege, ca toate neamurile care sunt în jurul meu.”"],[15,"pe acela pe care DOMNUL Dumnezeul vostru îl va alege ca împărat peste voi înșivă. Vei pune ca rege peste tine pe unul dintre frații tăi. Nu poți pune peste tine un străin, care nu este fratele tău."],[16,"Numai că nu va înmulți caii pentru el însuși și nu va face poporul să se întoarcă în Egipt, ca să-și înmulțească caii; pentru că Domnul ți-a spus: „Să nu te mai întorci pe acolo”."],[17,"El să nu-și înmulțească nevestele, ca să nu se întoarcă inima lui. El nu-și va înmulți mult argint și aur."],[18,"Când va ședea pe tronul împărăției sale, va scrie el însuși o copie a acestei legi într-o carte, din ceea ce este înaintea preoților levitici."],[19,"Acesta va fi cu el și va citi din ea în toate zilele vieții sale, ca să învețe să se teamă de DOMNUL Dumnezeul său, să păzească toate cuvintele acestei legi și aceste legi, și să le împlinească;"],[20,"ca inima lui să nu fie înălțată mai presus de frații săi și să nu se îndepărteze de la poruncă la dreapta sau la stânga, până la capăt, ca să-și prelungească zilele în împărăția lui, el și copiii lui, în mijlocul lui Israel."]]],[18,[[1,"Preoții și leviții, toată seminția lui Levi, nu vor avea parte și nici moștenire cu Israel. Să mănânce jertfele mistuite de foc ale Domnului și partea lui."],[2,"Ei nu vor avea moștenire între frații lor. Domnul este moștenirea lor, așa cum le-a vorbit."],[3,"Aceasta să fie datoria preoților de la popor, de la cei care aduc jertfă, fie că este bou sau oaie, pe care să o dea preotului: umărul, cei doi obraji și părțile interioare."],[4,"Să-i dai primele roade din grânul tău, din vinul tău nou și din untdelemnul tău și cele dintâi din lâna oilor tale."],[5,"Căci Domnul, Dumnezeul tău, l-a ales din toate semințiile tale, ca să slujească în numele Domnului, pe el și pe fiii lui pentru totdeauna."],[6,"Dacă un levit vine de la oricare dintre porțile tale din tot Israelul unde locuiește și vine cu toată dorința sufletului său în locul pe care îl va alege Domnul,"],[7,"apoi va sluji în numele Domnului Dumnezeului său, precum toți frații săi, leviții, care stau acolo înaintea Domnului."],[8,"Ei vor avea aceleași porții de mâncare, pe lângă cele care provin din vânzarea bunurilor familiei sale."],[9,"Când vei intra în țara pe care ți-o dă Domnul, Dumnezeul tău, să nu înveți să imiți urâciunile acelor neamuri."],[10,"Nu se va găsi la tine nimeni care să-și facă pe fiul sau pe fiica lui să treacă prin foc, cineva care se folosește de ghicitori, unul care spune averi, sau un vrăjitor, sau un vrăjitor,"],[11,"sau un fermecător, sau cineva care se consultă cu un spirit familiar, sau un vrăjitor sau un necromant."],[12,"Căci oricine face aceste lucruri este o urâciune înaintea Domnului. Din cauza acestor urâciuni, Domnul Dumnezeul tău le alungă dinaintea ta."],[13,"Vei fi fără prihană înaintea Domnului, Dumnezeului tău."],[14,"Căci aceste neamuri pe care le vei deposeda, ascultă de cei ce fac vrăjitorie și de ghicitori; dar pe tine, Domnul Dumnezeul tău nu ți-a îngăduit să faci așa."],[15,"Domnul, Dumnezeul tău, îți va ridica un proroc din mijlocul tău, dintre frații tăi, ca mine. Vei asculta de el."],[16,"Aceasta este după tot ce ai dorit de la Domnul, Dumnezeul tău, în Horeb, în ​​ziua adunării, zicând: „Să nu mai aud glasul Domnului Dumnezeului meu, nici să nu mai văd acest foc mare, ca să nu mor.”"],[17,"Domnul mi-a zis: „Bine au spus ceea ce au spus."],[18,"Le voi ridica un profet dintre frații lor, ca tine. Îmi voi pune cuvintele în gura lui și el le va spune tot ce îi voi porunci."],[19,"Se va întâmpla că oricui nu va asculta de cuvintele Mele, pe care le va rosti în numele Meu, îi voi cere."],[20,"Dar proorocul care rostește cu îndrăzneală un cuvânt în numele meu, pe care nu i-am poruncit să-l rostească, sau care vorbește în numele altor dumnezei, același profet va muri.”"],[21,"Poți spune în inima ta: „Cum vom cunoaște cuvântul pe care Domnul nu l-a spus?”"],[22,"Când un profet vorbește în numele Domnului, dacă lucrul nu urmează și nu se întâmplă, acesta este lucrul pe care Domnul nu l-a spus. Profetul a spus-o cu îndrăzneală. Nu te vei teme de el."]]],[19,[[1,"Când Domnul Dumnezeul tău va nimici națiunile a căror țara ți-o dă DOMNUL Dumnezeul tău, și tu le vei avea loc și vei locui în cetățile și în casele lor,"],[2,"să vă puneți deoparte trei cetăți în mijlocul țării voastre, pe care vi le dă în stăpânire DOMNUL Dumnezeul vostru."],[3,"Vei pregăti calea și vei împărți în trei părți hotarele țării tale pe care DOMNUL Dumnezeul tău ți-o dă moștenire, pentru ca fiecare ucigaș să poată fugi acolo."],[4,"Acesta este cazul ucigașului care va fugi acolo și va trăi: oricine își ucide aproapele fără să vrea și nu l-a urât în ​​trecut,"],[5,"ca atunci când un om intră în pădure cu vecinul său să taie lemne, iar mâna lui leagănă toporul pentru a tăia copacul, iar capul alunecă de la mâner și îl lovește pe aproapele său și va muri, el va fugi într-una din aceste orașe și va trăi."],[6,"Altfel, răzbunătorul sângelui ar putea să-l urmărească pe ucigaș în timp ce mânia aprinsă este în inima lui și să-l ajungă, pentru că drumul este lung, și să-l lovească de moarte, chiar dacă nu era vrednic de moarte, pentru că nu l-a urât în ​​trecut."],[7,"De aceea vă poruncesc să vă puneți deoparte trei cetăți."],[8,"Dacă Domnul Dumnezeul tău îți va lărgi hotarul, așa cum a jurat părinților tăi, și îți va da toată țara pe care a promis că o va da părinților tăi;"],[9,"și dacă veți păzi toată porunca aceasta, pe care vi le poruncesc astăzi, să iubiți pe Domnul Dumnezeul vostru și să umblați mereu pe căile Lui, atunci să mai adăugați trei cetăți pentru voi, pe lângă acestea trei."],[10,"Aceasta pentru ca sângele nevinovat să nu fie vărsat în mijlocul țării tale pe care ți-o dă ca moștenire DOMNUL Dumnezeul tău, lăsând sânge asupra ta."],[11,"Dar dacă cineva urăște pe aproapele său, îl pândește, se ridică împotriva lui, îl lovește de moarte și moare și fuge într-una din aceste cetăți;"],[12,"atunci bătrânii cetăţii sale să-l trimită şi să-l aducă acolo şi să-l dea în mâna răzbunătorului sângelui, ca să moară."],[13,"Ochiul tău nu va avea milă de el, ci vei curăța sângele nevinovat din Israel, ca să-ți fie bine."],[14,"Să nu îndepărtezi reperul aproapelui tău, pe care l-au pus ei din vechime, în moștenirea ta, pe care o vei moșteni, în țara pe care ți-o dă în stăpânire DOMNUL Dumnezeul tău."],[15,"Un singur martor nu se va ridica împotriva unui om pentru vreo nelegiuire sau pentru vreun păcat pe care el îl păcătuiește. Din gura a doi martori sau din gura a trei martori, se va stabili o chestiune."],[16,"Dacă un martor nedrept se ridică împotriva unui om ca să mărturisească împotriva lui despre fapte greșite,"],[17,"atunci amândoi bărbații dintre care este disputa să stea înaintea Domnului, înaintea preoților și a judecătorilor care vor fi în acele zile;"],[18,"iar judecătorii vor face o cercetare sârguincioasă; și iată, dacă martorul este un martor mincinos și a mărturisit mincinos împotriva fratelui său,"],[19,"atunci îi vei face așa cum a gândit să facă fratelui său. Deci vei îndepărta răul din mijlocul tău."],[20,"Cei care vor rămâne vor auzi și se vor teme și nu vor mai face niciodată un asemenea rău printre voi."],[21,"Ochii tăi nu vor avea milă: viață pentru viață, ochi pentru ochi, dinte pentru dinte, mână pentru mână, picior pentru picior."]]],[20,[[1,"Când vei ieși la luptă împotriva dușmanilor tăi și vei vedea cai, care și un popor mai numeros decât tine, nu te vei teme de ei; căci Domnul Dumnezeul tău, care te-a scos din ţara Egiptului, este cu tine."],[2,"Când te vei apropia de luptă, preotul se va apropia și va vorbi poporului:"],[3,"și le va spune: „Ascultă, Israele, te apropii astăzi ca să lupți împotriva vrăjmașilor tăi, să nu-ți slăbească inima, să nu te sperii, să nu tremurați și să nu vă speriați de ei;"],[4,"căci Domnul Dumnezeul tău este Cel care merge cu tine, ca să lupte pentru tine împotriva vrăjmașilor tăi, ca să te mântuiască.”"],[5,"Ofițerii vor vorbi poporului și vor zice: „Cine este un om care a zidit o casă nouă și n-a sfințit-o? Să se ducă și să se întoarcă la casa lui, ca să nu moară în luptă și să o dea alt om."],[6,"Care este om care a sădit o vie și nu a folosit rodul ei? Lasă-l să se ducă și să se întoarcă la casa lui, ca nu cumva să moară în luptă și alt om să folosească rodul ei."],[7,"Care este bărbatul care s-a angajat să se căsătorească cu o soție și nu a luat-o? Să se ducă și să se întoarcă la casa lui, ca nu cumva să moară în luptă și să o ia alt bărbat.”"],[8,"Ofițerii vor vorbi în continuare poporului și vor spune: „Ce om este înfricoșător și slăbit la inimă? Să se ducă și să se întoarcă la casa lui, ca să nu se topească inima fratelui său ca inima lui.”"],[9,"Când ofițerii vor termina de vorbit poporului, vor pune căpetenii de armate în fruntea poporului."],[10,"Când te apropii de un oraș pentru a lupta împotriva lui, atunci proclama-i pacea."],[11,"Se va întâmpla, dacă îți va da un răspuns de pace și ți se deschide, atunci toți oamenii care se găsesc acolo vor deveni muncitori forțați pentru tine și îți vor sluji."],[12,"Dacă nu va face pace cu tine, ci va face război împotriva ta, atunci o vei asedi."],[13,"Când DOMNUL Dumnezeul tău o va da în mâna ta, să-i lovești pe fiecare bărbat din ea cu tăișul sabiei;"],[14,"dar femeile, micuții, vitele și tot ce este în cetate, chiar și tot prada ei, să le iei drept pradă pentru tine. Poți folosi prada vrăjmașilor tăi, pe care ți-a dat-o Domnul, Dumnezeul tău."],[15,"Aşa să faci cu toate cetăţile care sunt foarte departe de tine, care nu sunt din cetăţile acestor neamuri."],[16,"Dar din cetăţile acestor popoare, pe care ţi le dă moştenire Domnul Dumnezeul tău, să nu mântuieşti nimic din ceea ce sufla;"],[17,"dar îi vei nimici cu desăvârșire: pe hetiți, pe amoriți, pe canaaniți, pe fereziți, pe heviți și pe iebusiți, așa cum ți-a poruncit Domnul Dumnezeul tău;"],[18,"ca să nu te învețe să urmezi toate urâciunile lor, pe care le-au făcut pentru zeii lor; așa ai păcătui împotriva Domnului Dumnezeului tău."],[19,"Când vei asedi o cetate mult timp, făcând război împotriva ei pentru a o lua, să nu-i distrugi copacii mânuind toporul împotriva lor; căci poți mânca din ele. Să nu-i tai, căci pomul câmpului este om să fie asediat de tine?"],[20,"Numai copacii pe care îi știi că nu sunt copaci pentru hrană, îi vei distruge și îi vei tăia. Vei zidi bastione împotriva cetății care se războiește cu tine, până când aceasta va cădea."]]],[21,[[1,"Dacă cineva este găsit ucis în țara pe care ți-o dă în stăpânire DOMNUL Dumnezeul tău, zăcând pe câmp, și nu se știe cine l-a lovit,"],[2,"atunci bătrânii voștri și judecătorii voștri vor ieși și vor măsura cetățile care sunt în jurul celui care a fost ucis."],[3,"Se va întâmpla ca bătrânii cetăţii care este cel mai aproape de omul ucis să ia o junincă din turmă, cu care nu a fost lucrată şi care nu a tras în jug."],[4,"Bătrânii acelei cetăți să coboare juninca într-o vale cu apă curgătoare, care nu este nici ară, nici semănată, și vor rupe gâtul junincii acolo, în vale."],[5,"Se vor apropia preoții, fiii lui Levi, pentru că pe aceștia i-a ales Domnul, Dumnezeul tău, ca să-i slujească și să-i binecuvânteze în Numele Domnului; și după cuvântul lor se va hotărî orice ceartă și orice atac."],[6,"Toți bătrânii acelei cetăți care este cel mai aproape de omul ucis să-și spele mâinile peste juninca căruia i s-a rupt gâtul în vale."],[7,"Ei vor răspunde și vor spune: „Mâinile noastre nu au vărsat acest sânge și nici ochii noștri nu l-au văzut."],[8,"Iartă, Doamne, poporul Tău Israel, pe care l-ai răscumpărat, și nu îngădui sânge nevinovat printre poporul Tău Israel.” Sângele le va fi iertat."],[9,"Deci, vei îndepărta sângele nevinovat din mijlocul tău, când vei face ceea ce este drept în ochii Domnului."],[10,"Când ieși la luptă împotriva vrăjmașilor tăi și Domnul Dumnezeul tău îi dă în mâinile tale și îi iei robi,"],[11,"și vezi printre prizonieri o femeie frumoasă și ești atras de ea și vrei să o iei de soție,"],[12,"apoi o vei aduce acasă la tine. Ea își va rade capul și își va tunde unghiile."],[13,"Ea își va scoate hainele robiei și va rămâne în casa ta și va plânge pe tatăl ei și pe mama ei o lună întreagă. După aceea, vei intra la ea și vei fi soțul ei, iar ea va fi soția ta."],[14,"Se va întâmpla, dacă nu vă bucurați de ea, atunci o veți lăsa să meargă unde vrea ea; dar nu o vei vinde deloc pe bani. Să nu te porți cu ea ca pe o sclavă, pentru că ai smerit-o."],[15,"Dacă un bărbat are două soții, una iubită și cealaltă urâtă, și i-au născut copii, atât pe cel iubit, cât și pe cel urât, și dacă primul născut este al ei, care a fost urât,"],[16,"atunci va fi, în ziua în care va lăsa pe fiii săi să moștenească ceea ce are, ca să nu dea fiului iubitului drepturile întâiului născut înaintea fiului celui urât, care este întâiul născut;"],[17,"dar el va recunoaște pe primul născut, fiul celui urât, dându-i o parte dublă din tot ce are; căci el este începutul puterii sale. Dreptul întâiului născut este al lui."],[18,"Dacă un om are un fiu încăpățânat și răzvrătit, care nu va asculta de glasul tatălui său sau de glasul mamei sale și, deși îl pedepsește, nu-i va asculta,"],[19,"atunci tatăl său și mama lui să-l apuce și să-l aducă la bătrânii cetății sale și la poarta locașului lui."],[20,"Ei vor spune bătrânilor cetăţii lui: „Acest fiu al nostru este încăpăţânat şi răzvrătit. El nu va asculta de vocea noastră. Este un lacom şi un beţiv.”"],[21,"Toți oamenii din cetatea lui îl vor ucide cu pietre. Deci vei îndepărta răul din mijlocul tău. Tot Israelul va auzi și se va teme."],[22,"Dacă un om a săvârșit un păcat demn de moarte și este pedepsit cu moartea și îl spânzurați pe un copac,"],[23,"trupul lui nu va rămâne toată noaptea pe copac, dar să-l îngropați în aceeași zi; căci cel spânzurat este blestemat de Dumnezeu. Nu spurca țara pe care ți-o dă ca moștenire Domnul Dumnezeul tău."]]],[22,[[1,"Să nu vezi boul sau oaia fratelui tău rătăcind și să te ascunzi de ei. Cu siguranță le vei aduce din nou fratelui tău."],[2,"Dacă fratele tău nu este aproape de tine sau dacă nu-l cunoști, atunci să-l aduci acasă în casa ta și să fie cu tine până când fratele tău o va căuta și să i-o dai înapoi."],[3,"Așa să faci cu măgarul lui. Așa să faci cu haina lui. Așa să faci cu orice lucru pierdut al fratelui tău, pe care el l-a pierdut și pe care l-ai găsit. S-ar putea să nu te ascunzi."],[4,"Să nu vezi măgarul fratelui tău sau boul lui căzut pe drum și să te ascunzi de ei. Cu siguranță îl vei ajuta să le ridice din nou."],[5,"Femeia să nu poarte haine bărbătești, nici bărbatul să nu se îmbrace în haine de femeie; căci oricine face aceste lucruri este o urâciune înaintea Domnului, Dumnezeului tău."],[6,"Dacă dai peste un cuib de pasăre pe drum, în vreun copac sau pe pământ, cu pui sau ouă, și găina care stă peste pui sau pe ouă, să nu iei găina cu puii."],[7,"Să lași găina să plece, dar puii să-i iei pentru tine, ca să-ți fie bine și să-ți prelungești zilele."],[8,"Când vei construi o casă nouă, să faci o balustradă în jurul acoperișului tău, ca să nu-ți aduci sânge pe casa dacă cade cineva de acolo."],[9,"Să nu semănă via ta cu două feluri de sămânță, ca să nu se spurce tot rodul, sămânța pe care ai semănat-o și sporul viei."],[10,"Să nu arati împreună cu un bou și un măgar."],[11,"Să nu purtați haine de lână și în țesute împreună."],[12,"Să vă faceți franjuri pe cele patru colțuri ale mantiei cu care vă acoperiți."],[13,"Dacă cineva își ia o soție și intră la ea, o urăște,"],[14,"o acuză de lucruri rușinoase, îi dă un nume rău și spune: „Am luat-o pe această femeie și, când m-am apropiat de ea, n-am găsit în ea semnele fecioriei”;"],[15,"atunci tatăl și mama domnișoarei vor lua și vor aduce semnele fecioriei domnișoarei bătrânilor cetății, la poartă."],[16,"Tatăl domnișoarei le va spune bătrânilor: „Mi-am dat fiica mea acestui bărbat ca soție și el o urăște."],[17,"Iată, el a acuzat-o de lucruri rușinoase, spunând: „Nu am găsit în fiica ta semnele fecioriei”; și totuși acestea sunt semnele fecioriei fiicei mele.” Ei vor întinde pânza înaintea bătrânilor cetăţii."],[18,"Bătrânii acelei cetăți vor lua omul și îl vor pedepsi."],[19,"Îi vor amenda cu o sută de sicli de argint și îi vor da tatălui domnișoarei, pentru că a dat un nume rău unei fecioare din Israel. Ea va fi soția lui. S-ar putea să nu o lase deoparte toate zilele lui."],[20,"Dar dacă acest lucru este adevărat, că semnele fecioriei nu s-au găsit la domnișoara,"],[21,"atunci o vor scoate pe domnișoara la ușa casei tatălui ei și bărbații din cetatea ei o vor ucide cu pietre, pentru că a făcut nebunie în Israel, ca să se desfrâneze în casa tatălui ei. Deci vei îndepărta răul din mijlocul tău."],[22,"Dacă un bărbat este găsit culcat cu o femeie căsătorită cu un soț, atunci vor muri amândoi, bărbatul care s-a culcat cu femeia și femeia. Deci vei îndepărta răul din Israel."],[23,"Dacă este o domnișoară care este fecioară, care s-a jurat să se căsătorească cu un bărbat, și un bărbat o găsește în oraș și se culcă cu ea,"],[24,"atunci îi vei aduce pe amândoi la poarta acelei cetăți și îi vei ucide cu pietre; doamna, pentru că nu a plâns, fiind în oraș; și bărbatul, pentru că a smerit-o pe soția aproapelui său. Deci vei îndepărta răul din mijlocul tău."],[25,"Dar dacă bărbatul o găsește pe doamna care s-a angajat să se căsătorească, iar bărbatul o silește și se culcă cu ea, atunci va muri numai bărbatul care s-a culcat cu ea;"],[26,"dar doamnei să nu faci nimic. Nu este în doamnă niciun păcat vrednic de moarte; căci cum se ridică un om împotriva aproapelui său și îl ucide, tot așa este și treaba aceasta;"],[27,"căci a găsit-o pe câmp, strigă doamna promisă să fie căsătorită și nu era nimeni să o salveze."],[28,"Dacă un bărbat găsește o doamnă care este fecioară, care nu este promisă să se căsătorească, o apucă și se culcă cu ea și se găsesc,"],[29,"atunci bărbatul care s-a culcat cu ea să dea tatălui doamnei cincizeci de sicli de argint. Ea va fi soția lui, pentru că el a smerit-o. S-ar putea să nu o lase deoparte toate zilele lui."],[30,"Un bărbat să nu ia soția tatălui său și să nu descopere fusta tatălui său."]]],[23,[[1,"Cel care este emasculat prin zdrobire sau tăiere nu va intra în adunarea Domnului."],[2,"O persoană născută dintr-o unire interzisă nu va intra în adunarea Domnului; nici până la al zecelea neam nimeni din ai lui să nu intre în adunarea Domnului."],[3,"Un amonit sau un moabit nu va intra în adunarea Domnului; nici până la al zecelea neam nimeni al lor să nu intre în adunarea Domnului pentru totdeauna,"],[4,"pentru că nu te-au întâlnit cu pâine și cu apă pe drum când ai ieșit din Egipt și pentru că l-au angajat împotriva ta pe Balaam, fiul lui Beor, din Petor din Mesopotamia, ca să te blesteme."],[5,"Cu toate acestea, Domnul Dumnezeul tău n-a vrut să asculte de Balaam, ci Domnul Dumnezeul tău a prefăcut blestemul într-o binecuvântare pentru tine, pentru că Domnul Dumnezeul tău te-a iubit."],[6,"Să nu cauți pacea și prosperitatea lor în toate zilele tale pentru totdeauna."],[7,"Să nu urăști un edomit, căci el este fratele tău. Să nu urăști un egiptean, pentru că ai locuit ca un străin în țara lui."],[8,"Copiii din a treia generație care li se naște pot intra în adunarea Domnului."],[9,"Când veți ieși și veți tăbăra împotriva dușmanilor voștri, atunci vă veți păzi de orice rău."],[10,"Dacă printre voi este cineva care nu este curat din cauza a ceea ce i se întâmplă noaptea, atunci să iasă din tabără. El nu va intra în tabără;"],[11,"dar când se va veni seara, el se va scalda în apă. Când soarele apune, va intra în tabără."],[12,"Vei avea un loc și în afara taberei, unde să te duci să te ajuți."],[13,"Vei avea o mistrie printre arme. Când te vei uşura, vei săpa cu ea, te vei întoarce şi vei acoperi excrementele tale;"],[14,"căci DOMNUL Dumnezeul tău umblă în mijlocul taberei tale, ca să te elibereze și să-ți dea dușmanii înaintea ta. De aceea tabăra ta să fie sfântă, ca să nu vadă ceva necurat în tine și să nu se îndepărteze de la tine."],[15,"Să nu dai stăpânului său un slujitor care a scăpat de stăpânul său la tine."],[16,"El va locui cu voi, printre voi, în locul pe care îl va alege, în interiorul uneia dintre porțile voastre, acolo unde îi va plăcea cel mai bine. Nu-l asupri."],[17,"Nu va fi nici o curvă dintre fiicele lui Israel, nici un sodomit dintre fiii lui Israel."],[18,"Să nu aduci în casa DOMNULUI, Dumnezeului tău, plata unei prostituate sau plata unui prostituat, pentru vreun jurământ; căci amândoi sunt o urâciune pentru Domnul Dumnezeul tău."],[19,"Să nu împrumuți fratelui tău cu dobândă: dobândă de bani, dobândă de mâncare, dobândă de orice se împrumută cu dobândă."],[20,"Puteți percepe o dobândă străină; dar nu cere fratelui tău dobândă, pentru ca Domnul Dumnezeul tău să te binecuvânteze în tot ceea ce ai pus mâna, în țara în care intri ca să o stăpânești."],[21,"Când faci un jurământ Domnului Dumnezeului tău, să nu te îndepărtezi să-l împlinești, căci Domnul Dumnezeul tău ți-l va cere; și ar fi păcat în tine."],[22,"Dar dacă te abții de la a face un jurământ, nu va fi păcat în tine."],[23,"Vei păzi și vei face ceea ce a ieșit din buzele tale. Orice ai făgăduit Domnului, Dumnezeului tău, ca dar de bunăvoie, pe care l-ai promis cu gura ta, trebuie să faci."],[24,"Când intri în via aproapelui tău, poți să mănânci de struguri după propria ta plăcere; dar să nu pui nimic în recipientul tău."],[25,"Când intri în grânul în picioare al aproapelui tău, poți smulge spicele cu mâna ta; dar să nu folosești o seceră pe grânele în picioare ale aproapelui tău."]]],[24,[[1,"Când un bărbat ia o soție și se căsătorește cu ea, atunci, dacă ea nu găsește favoare în ochii lui, pentru că a găsit ceva nepotrivit în ea, să-i scrie un act de divorț, să-l pună în mână și să o trimită din casa lui."],[2,"Când ea va pleca din casa lui, ea poate să meargă și să fie soția altui bărbat."],[3,"Dacă soțul din urmă o urăște și îi scrie un certificat de divorț, îl pune în mână și o trimite afară din casa lui; sau dacă moare ultimul soț, care a luat-o ca soție;"],[4,"fostul ei soț, care a trimis-o, nu o poate lua din nou ca soție după ce ea se va pângări; căci aceasta ar fi o urâciune pentru Domnul. Să nu păcătuiești țara pe care ți-o dă ca moștenire DOMNUL Dumnezeul tău."],[5,"Când un bărbat își ia o nouă nevastă, nu va ieși în armată și nu i se va atribui nicio treabă. El va fi liber acasă un an și își va bucura soția pe care a luat-o."],[6,"Nimeni nu va lua ca gaj moara sau piatra de moara de sus, pentru că el ia o viață în gaj."],[7,"Dacă se găsește un om furând pe vreunul dintre frații săi dintre copiii lui Israel și îl tratează ca pe un sclav sau îl vinde, atunci hoțul va muri. Deci vei îndepărta răul din mijlocul tău."],[8,"Ai grijă în urgia leprei, să păzești cu sârguință și să faci după tot ce te învață preoții levitici. Așa cum le-am poruncit, așa veți avea grijă să faceți."],[9,"Adu-ți aminte ce a făcut Domnul, Dumnezeul tău, Mariei, pe drum, când ai ieșit din Egipt."],[10,"Când împrumuți aproapelui tău orice fel de împrumut, să nu intri în casa lui ca să-i iei gaj."],[11,"Să stai afară, iar omul căruia îi împrumuți să-ți aducă gajul afară."],[12,"Dacă este un om sărac, să nu te culci cu gajul lui."],[13,"Îi vei întoarce garanția la apusul soarelui, ca să doarmă în haina lui și să te binecuvânteze. Pentru tine va fi dreptate înaintea Domnului, Dumnezeului tău."],[14,"Să nu asupriți un angajat sărac și sărac, fie că este unul dintre frații voștri, fie unul dintre străinii care sunt în țara voastră, la porțile voastre."],[15,"În ziua lui, să-i dai plata lui și soarele să nu apune peste el, căci el este sărac și își pune inima asupra lui, ca să nu strige împotriva ta către DOMNUL și să fie păcat pentru tine."],[16,"Părinţii nu vor fi omorâţi pentru copii, nici copiii nu vor fi omorâţi pentru părinţi. Fiecare om va fi pedepsit cu moartea pentru propriul său păcat."],[17,"Să nu lipsiți de dreptate pe străin sau pe orfan și să nu luați în gaj hainele văduvei;"],[18,"dar să-ți aduci aminte că ai fost rob în Egipt și că Domnul Dumnezeul tău te-a răscumpărat acolo. De aceea vă poruncesc să faceți acest lucru."],[19,"Când vei culege secerișul în câmpul tău și vei uita un snop pe câmp, să nu te mai duci să-l iei. Să fie pentru străinul, pentru orfan și pentru văduvă, ca Domnul Dumnezeul tău să te binecuvânteze în toată lucrarea mâinilor tale."],[20,"Când îți vei bate măslinul, nu vei mai trece peste ramuri. Să fie pentru străin, pentru orfan și pentru văduvă."],[21,"Când vă veți culege via, să nu o culegeți după voi înșivă. Să fie pentru străin, pentru orfan și pentru văduvă."],[22,"Îți vei aminti că ai fost sclav în țara Egiptului. De aceea vă poruncesc să faceți acest lucru."]]],[25,[[1,"Dacă există o ceartă între oameni și ei vin la judecată și judecătorii îi judecă, atunci ei vor îndreptăți pe cei drepți și vor condamna pe cei răi."],[2,"Dacă omul rău este vrednic să fie bătut, judecătorul să-l facă să se culce și să fie bătut înaintea lui, după răutatea lui, după număr."],[3,"El îl poate condamna la cel mult patruzeci de dungi. El nu va da mai mult, ca nu cumva, dacă va da mai mult și îl va bate mai mult decât atâtea lovituri, atunci fratele tău va fi înjosit înaintea ta."],[4,"Să nu dai botnița boul când el călcă grânul."],[5,"Dacă frații locuiesc împreună și unul dintre ei moare și nu are fiu, soția mortului să nu se căsătorească afară cu un străin. Fratele bărbatului ei să intre la ea și să o ia de nevastă și să îndeplinească datoria fratelui bărbatului față de ea."],[6,"Se va întâmpla ca întâiul născut pe care ea îl va naște va urma în numele fratelui său care a murit, pentru ca numele lui să nu fie șters din Israel."],[7,"Dacă bărbatul nu vrea să ia femeia fratelui său, soția fratelui său să se suie la poartă la bătrâni și să zică: „Fratele soțului meu refuză să ridice fratelui său un nume în Israel; nu va îndeplini datoria de frate al bărbatului față de mine”."],[8,"Atunci bătrânii cetăţii lui îl vor chema şi vor vorbi cu el. Dacă se ridică și spune: „Nu vreau să o iau”,"],[9,"atunci soția fratelui său va veni la el în fața bătrânilor, și-și va dezlega încălțămintea de pe picior și îi va scuipa în față. Ea va răspunde și va spune: „Așa se va face omului care nu zidește casa fratelui său”."],[10,"Numele lui va fi numit în Israel: „Casa celui căruia i s-a scos încălțămintea”."],[11,"Când bărbații se luptă unul împotriva celuilalt și soția unuia se apropie pentru a-și scăpa bărbatul din mâna celui care îl lovește și își întinde mâna și-l apucă de părțile sale intime,"],[12,"atunci îi vei tăia mâna. Ochiul tău nu va avea milă."],[13,"Nu vei avea în geantă diverse greutăți, una grea și una ușoară."],[14,"Să nu ai în casa ta diferite măsuri, una mare și alta mică."],[15,"Vei avea o greutate perfectă și justă. Vei avea o măsură perfectă și dreaptă, pentru ca zilele tale să se lungească în țara pe care ți-o dă Domnul, Dumnezeul tău."],[16,"Căci toți cei ce fac astfel de lucruri, toți cei ce fac nedreptate, sunt o urâciune înaintea Domnului, Dumnezeului tău."],[17,"Adu-ți aminte ce ți-a făcut Amalec pe drum când ai ieșit din Egipt,"],[18,"cum te-a întâlnit pe drum și a lovit pe cei din spate dintre voi, pe toți cei slăbiți în spatele vostru, când erați leșinați și obosiți; și nu se temea de Dumnezeu."],[19,"De aceea, când DOMNUL, Dumnezeul tău, îți va da odihnă de toți vrăjmașii tăi din jur, în țara pe care ți-o dă ca moștenire DOMNUL Dumnezeul tău, ca să o stăpânești, să ștergi amintirea lui Amalec de sub cer. Nu vei uita."]]],[26,[[1,"Când vei intra în țara pe care ți-o dă ca moștenire DOMNUL Dumnezeul tău, să o stăpânești și să locuiești în ea,"],[2,"ca să iei cîteva din primele din toate roadele pământului, pe care le vei aduce din ţara ta pe care ţi-o dă DOMNUL Dumnezeul tău. Să-l pui într-un coș și să te duci la locul pe care-l va alege Domnul Dumnezeul tău, ca să-și facă numele să locuiască acolo."],[3,"Să vii la preotul care va fi în acele zile și să-i spui: „Azi mărturisesc Domnului, Dumnezeului tău, că am venit în țara pe care Domnul a jurat părinților noștri că ne-o va da.”"],[4,"Preotul să ia coșul din mâna ta și să-l așeze înaintea altarului Domnului Dumnezeului tău."],[5,"Vei răspunde și vei spune înaintea Domnului Dumnezeului tău: „Tatăl meu a fost un sirian gata să piară. S-a pogorât în ​​Egipt și a locuit acolo, puțini la număr. Acolo s-a făcut un neam mare, puternic și populat."],[6,"Egiptenii ne-au maltratat, ne-au chinuit și ne-au impus muncă silnică."],[7,"Atunci am strigat către Domnul, Dumnezeul părinţilor noştri. Domnul a auzit glasul nostru și a văzut necazul nostru, truda și asuprirea noastră."],[8,"Domnul ne-a scos din Egipt cu o mână puternică, cu un braț întins, cu mare groază, cu semne și cu minuni;"],[9,"și ne-a adus în acest loc și ne-a dat această țară, o țară în care curge lapte și miere."],[10,"Acum, iată, am adus cele dintâi din rodul pământului, pe care mi l-ai dat Tu, Domnul.” Să o pui înaintea Domnului Dumnezeului tău și să te închini înaintea Domnului Dumnezeului tău."],[11,"Te vei bucura de tot binele pe care DOMNUL Dumnezeul tău l-a dat ție și casei tale, ție, levitului și străinului care este printre voi."],[12,"Când vei termina de zeciuială toată zecimea sporului tău în al treilea an, care este anul zeciuială, atunci să o dai levitului, străinului, orfanului și văduvei, ca să mănânce la porțile tale și să se săture."],[13,"Să spui înaintea Domnului Dumnezeului tău: „Am îndepărtat lucrurile sfinte din casa mea și le-am dat și levitului, străinului, orfanului și văduvei, după toate poruncile tale pe care mi le-ai poruncit. Nu am călcat nici una din poruncile tale și nici nu le-am uitat."],[14,"N-am mâncat din el în doliu, nici n-am scos nimic din el cât eram necurat, nici nu am dat din el pentru morți. Am ascultat glasul Domnului Dumnezeului meu. Am făcut după tot ce mi-ai poruncit."],[15,"Privește din locașul tău sfânt, din cer, și binecuvântează pe poporul tău Israel și pământul pe care ni l-ai dat, așa cum ai jurat părinților noștri, o țară în care curge lapte și miere.”"],[16,"Astăzi, Domnul Dumnezeul tău îți poruncește să împlinești aceste legi și porunci. De aceea le vei păzi și le vei face din toată inima ta și din tot sufletul tău."],[17,"Ai spus astăzi că Domnul este Dumnezeul tău și că vei umbla pe căile Lui, că vei păzi legile, poruncile și rânduielile Lui și vei asculta de glasul Lui."],[18,"Domnul a spus astăzi că ești un popor pentru stăpânirea Lui, așa cum ți-a promis și că trebuie să păzești toate poruncile Lui."],[19,"El te va înălța mai presus de toate neamurile pe care le-a făcut, în laudă, în nume și în cinste, și să fii un popor sfânt pentru Domnul Dumnezeul tău, așa cum a spus El."]]],[27,[[1,"Moise și bătrânii lui Israel au poruncit poporului, zicând: „Păziți toată porunca pe care vi le poruncesc astăzi."],[2,"În ziua când vei trece Iordanul în țara pe care ți-o dă Domnul Dumnezeul tău, să-ți ridici pietre mari și să le îmbraci cu tencuială."],[3,"Să scrii pe ei toate cuvintele acestei legi, după ce vei trece, ca să ajungi în țara pe care ți-o dă Domnul Dumnezeul tău, o țară în care curge lapte și miere, precum ți-a promis Domnul, Dumnezeul părinților tăi."],[4,"Când vei trece Iordanul, vei ridica aceste pietre, pe care ți le poruncesc astăzi, pe muntele Ebal și le vei îmbrăca cu tencuială."],[5,"Acolo vei zidi un altar Domnului Dumnezeului tău, un altar de pietre. Nu trebuie să folosiți nicio unealtă de fier pe ele."],[6,"Vei zidi altarul Domnului Dumnezeului tău din pietre netăiate. Să aduci pe ea arderi de tot Domnului, Dumnezeului tău."],[7,"Să jertfești jertfe de mulțumire și să mănânci acolo. Te vei bucura înaintea Domnului Dumnezeului tău."],[8,"Să scrii pe pietre toate cuvintele acestei legi foarte clar.”"],[9,"Moise și preoții levitici au vorbit întregului Israel și au zis: „Taci și ascultă, Israele, că astăzi ai devenit poporul Domnului Dumnezeului tău."],[10,"De aceea, vei asculta de glasul Domnului Dumnezeului tău și vei împlini poruncile și legile Lui, pe care ți le poruncesc astăzi.”"],[11,"Moise a poruncit poporului în aceeași zi, zicând:"],[12,"„Aceștia vor sta pe muntele Garizim, ca să binecuvânteze poporul, când vei trece Iordanul: Simeon, Levi, Iuda, Isahar, Iosif și Beniamin."],[13,"Aceștia vor sta pe muntele Ebal pentru blestem: Ruben, Gad, Așer, Zabulon, Dan și Neftali."],[14,"Cu glas tare, leviții vor spune tuturor bărbaților lui Israel:"],[15,"„Blestemat să fie omul care face o imagine gravată sau topită, o urâciune înaintea Domnului, lucrarea mâinilor meșteșugarului, și o ridică în ascuns.”"],[16,"„Blestemat să fie cel care necinstește pe tatăl său sau pe mama sa.”"],[17,"„Blestemat să fie cel care îndepărtează reperul aproapelui său.”"],[18,"„Blestemat să fie cel care rătăcește pe orb pe drum.”"],[19,"„Blestemat să fie cel care reține dreptatea străinului, orfanului și văduvei.”"],[20,"„Blestemat să fie cel ce se culcă cu soția tatălui său, pentru că necinstește patul tatălui său.”"],[21,"„Blestemat să fie cel care se culcă cu orice fel de animal.”"],[22,"„Blestemat să fie cel care se culcă cu sora lui, cu fiica tatălui său sau cu fiica mamei sale.”"],[23,"„Blestemat să fie cel care se culcă cu soacra sa.”"],[24,"„Blestemat să fie cel care-și ucide aproapele în secret.”"],[25,"„Blestemat să fie cel care ia mită pentru a ucide o persoană nevinovată.”"],[26,"„Blestemat să fie cel care nu susține cuvintele acestei legi, împlinindu-le.”"]]],[28,[[1,"Dacă veți asculta cu sârguință de glasul Domnului Dumnezeului vostru și veți păzi să împliniți toate poruncile Lui pe care ți le poruncesc astăzi, Domnul Dumnezeul tău te va înălța mai presus de toate neamurile pământului."],[2,"Toate aceste binecuvântări vor veni peste tine și te vor atinge, dacă vei asculta de glasul Domnului Dumnezeului tău."],[3,"Vei fi binecuvântat în cetate și vei fi binecuvântat pe câmp."],[4,"Vei fi binecuvântat în rodul trupului tău, rodul pământului tău, rodul animalelor tale, sporul turmei tale și puii turmei tale."],[5,"Coșul tău și frământatul tău vor fi binecuvântate."],[6,"Vei fi binecuvântat când vei intra și vei fi binecuvântat când vei ieși."],[7,"Domnul va face ca vrăjmașii tăi care se vor ridica împotriva ta să fie loviți înaintea ta. Ei vor ieși împotriva ta pe o cale și vor fugi dinaintea ta pe șapte căi."],[8,"Domnul va porunci binecuvântarea asupra ta în hambarele tale și în tot ceea ce vei pune mâna. El te va binecuvânta în țara pe care ți-o dă Domnul, Dumnezeul tău."],[9,"Domnul te va întări ca un popor sfânt pentru El, după cum ți-a jurat, dacă vei păzi poruncile Domnului Dumnezeului tău și vei umbla pe căile Lui."],[10,"Toate popoarele pământului vor vedea că ești chemat pe numele Domnului și se vor teme de tine."],[11,"Domnul îți va da prosperitate din belșug în rodul trupului tău, în rodul turmei tale și în rodul pământului tău, în țara pe care Domnul a jurat părinților tăi că ți-o va da."],[12,"Domnul îți va deschide comoara Sa cea bună pe cer, ca să dea ploaia țării tale la vremea ei și să binecuvânteze toată lucrarea mâinii tale. Vei împrumuta multor neamuri și nu vei împrumuta."],[13,"Domnul te va face cap, nu coada. Tu vei fi numai sus și nu vei fi dedesubt, dacă vei asculta de poruncile Domnului Dumnezeului tău, pe care ți le poruncesc astăzi, să le păzești și să le împlinești,"],[14,"și să nu te îndepărtezi de la niciunul din cuvintele pe care ți le poruncesc astăzi, la dreapta sau la stânga, ca să mergi după alți dumnezei, ca să le slujească."],[15,"Dar, dacă nu vei asculta de glasul Domnului Dumnezeului tău, ca să păzești să împliniți toate poruncile și legile Lui pe care ți le poruncesc astăzi, toate aceste blesteme vor veni peste tine și te vor atinge."],[16,"Vei fi blestemat în cetate și vei fi blestemat pe câmp."],[17,"Coșul tău și frământatul tău vor fi blestemate."],[18,"Rodul trupului tău, rodul pământului tău, sporul turmei tale și puii turmei tale vor fi blestemate."],[19,"Vei fi blestemat când vei intra și vei fi blestemat când vei ieși."],[20,"Domnul va trimite asupra ta blestem, dezamăgire și mustrare în tot ceea ce ai pus mâna ta, până vei fi nimicit și până vei pieri repede, din cauza răutății faptelor tale, prin care M-ai părăsit."],[21,"Domnul va face să se lipească de tine ciuma, până te va nimici din țara în care intri ca să o stăpânești."],[22,"DOMNUL vă va lovi cu mistuire, cu febră, cu inflamare, cu căldură aprinsă, cu sabie, cu puzdă și cu mucegai. Ei te vor urmări până vei pieri."],[23,"Cerul tău care este deasupra capului tău va fi de aramă, iar pământul care este sub tine va fi de fier."],[24,"Domnul va face ploaia pământului tău praf și praf. Se va coborî peste tine din cer, până vei fi nimicit."],[25,"Domnul te va lovi înaintea dușmanilor tăi. Vei ieși împotriva lor pe o singură cale și vei fugi înaintea lor pe șapte căi. Vei fi aruncat înainte și înapoi printre toate împărățiile pământului."],[26,"Cadavrele voastre vor fi hrană pentru toate păsările cerului și pentru animalele pământului; și nu va fi nimeni care să-i sperie."],[27,"Domnul te va lovi cu furunculele Egiptului, cu tumorile, cu scorbutul și cu mâncărimea, de care nu te poți vindeca."],[28,"Domnul te va lovi cu nebunie, cu orbire și cu uimirea inimii."],[29,"Vei bâjbâi la amiază, precum bâjbâie orbii în întuneric, și nu vei prospera în căile tale. Vei fi doar asuprit și jefuit mereu și nu va fi nimeni care să te salveze."],[30,"Te vei logodi cu o soție și un alt bărbat se va culca cu ea. Vei construi o casă și nu vei locui în ea. Vei sădi o vie și nu vei folosi rodul ei."],[31,"Boul tău va fi junghiat înaintea ochilor tăi și nu vei mânca nimic din el. Măgarul tău va fi luat cu violență dinaintea feței tale și nu ți se va da înapoi. Oile tale vor fi date dușmanilor tăi și nu vei avea pe cine să te salveze."],[32,"Fiii și fiicele voastre vor fi dați altui popor. Ochii tăi vor privi și eșua de dor după ei toată ziua. Nu va fi nicio putere în mâna ta."],[33,"O națiune pe care nu o cunoști va mânca din roadele pământului tău și din toată lucrarea ta. Vei fi doar asuprit și zdrobit mereu,"],[34,"pentru ca priveliștile pe care le vezi cu ochii tăi să te înnebunească."],[35,"Domnul te va lovi în genunchi și în picioare cu o furunculă dureroasă, de care nu te poți vindeca, de la talpa piciorului până la coroana capului."],[36,"Domnul vă va aduce pe voi și pe regele vostru pe care îl veți pune peste voi într-un neam pe care nu l-ați cunoscut, nici tu, nici părinții voștri. Acolo vei sluji altor zei ai lemnului și ai pietrei."],[37,"Vei deveni o uimire, un proverb și o batjocură printre toate popoarele de unde te va duce Domnul."],[38,"Vei duce multă sămânță pe câmp și vei strânge puțin, căci lăcustele o va mistui."],[39,"Vei sădi vii și le vei îmbrăca, dar din vin nu vei bea și nici nu vei cules, pentru că le vor mânca viermii."],[40,"Vei avea măslini în toate hotarele tale, dar nu te vei unge cu ulei, căci măslinii tăi vor scădea."],[41,"Vei avea fii și fiice, dar ei nu vor fi ai tăi, căci vor merge în robie."],[42,"Lăcustele vor consuma toți copacii tăi și fructele pământului tău."],[43,"Străinul care este printre voi se va urca deasupra ta din ce în ce mai sus, iar tu vei coborî din ce în ce mai jos."],[44,"El îți va împrumuta, iar tu nu-i vei împrumuta. El va fi capul, iar tu vei fi coada."],[45,"Toate aceste blesteme vor veni peste tine, te vor urmări și te vor atinge, până vei fi nimicit, pentru că n-ai ascultat de glasul Domnului, Dumnezeului tău, ca să păzești poruncile și legile Lui pe care ți le-a poruncit."],[46,"Ele vor fi un semn și o minune pentru tine și pentru urmașii tăi pentru totdeauna."],[47,"Pentru că n-ai slujit Domnului Dumnezeului tău cu bucurie și cu bucurie inimii, din pricina abundenței tuturor lucrurilor;"],[48,"de aceea, veţi sluji vrăjmaşilor voştri pe care Domnul îi trimite împotriva voastră, în foame, în sete, în goliciune şi în lipsă de toate. Îți va pune un jug de fier pe gât până te va nimici."],[49,"Domnul va aduce împotriva ta un neam de departe, de la capătul pământului, precum zboară vulturul: un neam a cărui limbă nu o vei înțelege,"],[50,"o națiune cu expresii faciale acerbe, care nu-i respectă pe bătrâni și nici nu le arată favoare celor tineri."],[51,"Ei vor mânca din roadele vitelor tale și din roadele pământului tău, până vei fi nimicit. De asemenea, nu-ți vor lăsa grâne, vin nou, untdelemn, sporul turmei tale sau puii turmei tale, până nu te vor face să pierzi."],[52,"Te vor asedi în toate porțile tale până când zidurile tale înalte și întărite, în care te-ai încrezut, se vor prăbuși în toată țara ta. Te vor asedi în toate porțile tale, în toată țara pe care ți-a dat-o DOMNUL Dumnezeul tău."],[53,"Vei mânca din rodul propriului tău trup, din carnea fiilor tăi și a fiicelor tale, pe care ți-a dat Domnul, Dumnezeul tău, în asediul și în necazul cu care te vor chinui vrăjmașii tăi."],[54,"Bărbatul care este blând printre voi și foarte delicat, ochiul lui va fi rău față de fratele său, față de soția pe care o iubește și față de rămășița copiilor săi, pe care i-a rămas,"],[55,"ca să nu-i dea nimănui din carnea copiilor săi pe care să-i mănânce, pentru că nu-i mai are nimic, în asediul și în necazul cu care vrăjmașul tău te va frământa în toate porțile tale."],[56,"Femeia duioasă și delicată dintre voi, care nu s-ar îndrăzni să-și pună talpa piciorului pe pământ pentru delicatețe și tandrețe, ochiul ei va fi rău față de soțul pe care îl iubește, față de fiul ei, față de fiica ei,"],[57,"față de puiul ei care iese dintre picioarele ei și față de copiii ei pe care îi naște; căci ea le va mânca pe ascuns, din lipsă de toate lucrurile, în asediul și în necazul cu care vrăjmașul tău te va tulbura la porțile tale."],[58,"Dacă nu veți păzi să împliniți toate cuvintele acestei legi, care sunt scrise în această carte, ca să vă temeți de acest nume glorios și înfricoșător, DOMNUL Dumnezeul vostru,"],[59,"atunci Domnul va face înfricoșătoare urgiile tale și urgiile urmașilor tăi, chiar urgii mari și de lungă durată și boli grele și de lungă durată."],[60,"El va aduce înapoi asupra ta toate bolile Egiptului, de care te-ai temut; și se vor lipi de tine."],[61,"De asemenea, orice boală și orice urgie care nu este scrisă în cartea acestei legi, Domnul le va aduce peste tine până vei fi nimicit."],[62,"Veți rămâne puțini la număr, chiar dacă ați fost ca stelele cerului în mulțime, pentru că n-ați ascultat de glasul Domnului Dumnezeului vostru."],[63,"Se va întâmpla că, după cum s-a bucurat Domnul de tine, să-ți facă bine și să te înmulțească, așa se va bucura Domnul de tine, ca să te piară și să te piardă. Vei fi smuls din țara pe care vei intra să o stăpânești."],[64,"Domnul te va risipi printre toate popoarele, de la un capăt al pământului până la celălalt capăt al pământului. Acolo vei sluji altor dumnezei pe care nu i-ai cunoscut, nici tie nici părinţilor tăi, chiar lemnului şi piatră."],[65,"Printre aceste neamuri nu vei găsi uşurinţă şi nu va fi odihnă pentru talpa piciorului tău; dar Domnul îți va da acolo o inimă tremurândă, ochi slăbiți și suflet dornic."],[66,"Viața ta va atârna în îndoială în fața ta. Îți va fi teamă zi și noapte și nu vei avea nicio asigurare cu privire la viața ta."],[67,"Dimineața vei spune: „Aș vrea să fie seară!” iar seara vei spune: „Aș vrea să fie dimineață!” pentru frica inimii tale de care te vei teme și pentru priveliștile pe care le vor vedea ochii tăi."],[68,"Domnul vă va aduce din nou în Egipt cu corăbii, pe calea căreia v-am spus că nu o veți mai vedea niciodată. Acolo vă veți oferi vrăjmașilor voștri pentru sclave și femei și nimeni nu vă va cumpăra."]]],[29,[[1,"Acestea sunt cuvintele legământului pe care Domnul ia poruncit lui Moise să-l facă cu copiii lui Israel în țara Moabului, pe lângă legământul pe care l-a făcut cu ei în Horeb."],[2,"Moise a chemat pe tot Israelul și le-a zis:"],[3,"marile încercări pe care le-au văzut ochii tăi, semnele și acele mari minuni."],[4,"Dar Domnul nu v-a dat până în ziua de azi o inimă să cunoașteți, ochi să vedeți și urechi să auzi."],[5,"Te-am condus patruzeci de ani în pustie. Hainele tale nu ți-au îmbătrânit și sandalele tale nu ți-au îmbătrânit picioarele."],[6,"N-ai mâncat pâine, nici nu ai băut vin sau băutură tare, ca să știi că Eu sunt Domnul Dumnezeul tău."],[7,"Când ai ajuns în acest loc, Sihon, împăratul Heșbonului, și Og, împăratul Basanului, au ieșit împotriva noastră la luptă și i-am lovit."],[8,"Le-am luat țara și am dat-o ca moștenire rubeniților și gadiților și jumătății de seminție a manasiților."],[9,"De aceea, păzește cuvintele acestui legământ și împlinește-le, ca să prosperi în tot ceea ce faci."],[10,"Voi toți stați astăzi în fața Domnului Dumnezeului vostru: capeții voastre, semințiile voastre, bătrânii voștri și căpeteniile voastre, chiar toți bărbații lui Israel,"],[11,"micuții voștri, soțiile voastre și străinii care sunt în mijlocul taberelor voastre, de la cel care vă taie lemnele până la cel care vă trage apa,"],[12,"ca să poți intra în legământul Domnului Dumnezeului tău și în jurământul lui, pe care Domnul Dumnezeul tău îl face astăzi cu tine,"],[13,"ca să te întărească astăzi ca popor al său și să fie Dumnezeul tău, așa cum ți-a spus și cum a jurat părinților tăi, lui Avraam, Isaac și Iacov."],[14,"Nici eu nu fac acest legământ și acest jurământ numai cu tine,"],[15,"dar cu cei care stau astăzi aici cu noi înaintea Domnului Dumnezeului nostru, și de asemenea cu cei care nu sunt astăzi aici cu noi"],[16,"(căci știți cum am trăit în țara Egiptului și cum am trecut prin mijlocul neamurilor prin care ați trecut;"],[17,"și ai văzut urâciunile lor și idolii lor de lemn, piatră, argint și aur, care erau printre ei);"],[18,"ca să nu fie printre voi bărbat, femeie, familie sau trib a căror inimă se abate astăzi de la Domnul Dumnezeul nostru, ca să meargă să slujească zeilor acelor neamuri; ca să nu fie printre voi o rădăcină care să producă otravă amară;"],[19,"și se întâmplă, când aude cuvintele acestui blestem, să se binecuvânteze pe sine în inima lui, zicând: „Voi avea pace, deși voi umbla în încăpățânarea inimii mele”, pentru a nimici umed cu uscatul."],[20,"Domnul nu-l va ierta, dar atunci mânia Domnului și gelozia lui vor aprinde împotriva acestui om și tot blestemul scris în această carte va cădea asupra lui și Domnul îi va șterge numele de sub cer."],[21,"Domnul îl va pune deoparte pentru rău din toate triburile lui Israel, după toate blestemele legământului scrise în această carte a Legii."],[22,"Generația viitoare, copiii tăi, care se vor ridica după tine și străinul care va veni dintr-o țară îndepărtată, va spune, când va vedea urgiile acelei țări și bolile de care a îmbolnăvit-o Domnul:"],[23,"că toată țara lui este sulf, sare și ardere, că nu se seamănă, nu produce și nici iarbă nu crește în ea, precum răsturnarea Sodomei, Gomorei, Adma și Țeboimului, pe care Domnul le-a răsturnat în mânia Sa și în mânia Sa."],[24,"Chiar și toate neamurile vor zice: „De ce a făcut Domnul aceasta țării acesteia? Ce înseamnă căldura acestei mari mânii?”"],[25,"Atunci oamenii vor zice: „Pentru că au părăsit legământul Domnului, Dumnezeul părinţilor lor, pe care l-a făcut cu ei când i-a scos din ţara Egiptului,"],[26,"și s-au dus și au slujit altor dumnezei și s-au închinat lor, dumnezei pe care ei nu i-au cunoscut și pe care nu le-a dat."],[27,"De aceea, mânia Domnului a aprins împotriva acestei țări, ca să aducă asupra ei toate blestemele care sunt scrise în această carte."],[28,"Domnul i-a scos din țara lor cu mânie, cu mânie și cu mare mânie și i-a aruncat într-o altă țară, așa cum este astăzi.”"],[29,"Lucrurile ascunse sunt ale Domnului Dumnezeului nostru; dar lucrurile care sunt descoperite sunt ale noastre și ale copiilor noștri pentru totdeauna, ca să putem împlini toate cuvintele acestei legi."]]],[30,[[1,"Se va întâmpla, când vor veni asupra ta toate aceste lucruri, binecuvântarea și blestemul, pe care ți le-am pus înainte, și le vei aduce aminte printre toate neamurile pe care te-a alungat Domnul, Dumnezeul tău,"],[2,"și întoarceți-vă la Domnul, Dumnezeul vostru, și ascultați glasul Lui, după tot ce vă poruncesc astăzi, ție și copiii tăi, din toată inima ta și din tot sufletul tău,"],[3,"că atunci Domnul Dumnezeul tău te va elibera din robie, va avea milă de tine și se va întoarce și te va aduna din toate popoarele pe care te-a împrăștiat Domnul Dumnezeul tău."],[4,"Dacă proscrișii tăi sunt în marginile cerurilor, de acolo te va aduna Domnul Dumnezeul tău și de acolo te va aduce înapoi."],[5,"Domnul Dumnezeul tău te va aduce în țara pe care au stăpânit-o părinții tăi și tu o vei stăpâni. El vă va face bine și vă va spori numărul mai mult decât părinții voștri."],[6,"Domnul, Dumnezeul tău, îți va tăia împrejur inima și inima urmașilor tăi, ca să iubești pe Domnul Dumnezeul tău din toată inima ta și din tot sufletul tău, ca să trăiești."],[7,"Domnul, Dumnezeul tău, va pune toate aceste blesteme asupra dușmanilor tăi și asupra celor ce te urăsc, care te-au prigonit."],[8,"Te vei întoarce și vei asculta de glasul Domnului și vei împlini toate poruncile Lui pe care ți le poruncesc astăzi."],[9,"Domnul, Dumnezeul tău, te va face să prosperi în toată lucrarea mâinii tale, în rodul trupului tău, în rodul vitelor tale și în rodul pământului tău, pentru bine; căci Domnul se va bucura iarăși de tine în bine, așa cum s-a bucurat de părinții tăi,"],[10,"dacă vei asculta de glasul Domnului Dumnezeului tău și vei păzi poruncile și legile Lui, care sunt scrise în această carte a Legii, dacă te vei întoarce la Domnul Dumnezeul tău din toată inima ta și din tot sufletul tău."],[11,"Căci această poruncă pe care ți-o dau astăzi nu este prea grea pentru tine și nici prea îndepărtată."],[12,"Nu este în cer să zici: „Cine se va sui pentru noi la cer, să ni-l aducă și să ne-o vestească, ca să o facem?”"],[13,"Nici dincolo de mare nu este ca să spui: „Cine va trece peste mare pentru noi, să ni-l aducă și să ne-o vestească, ca să o facem?”"],[14,"Dar cuvântul este foarte aproape de tine, în gura și în inima ta, ca să-l faci."],[15,"Iată, am pus înaintea ta astăzi viața și prosperitatea, moartea și răul."],[16,"Căci îți poruncesc astăzi să iubești pe Domnul Dumnezeul tău, să umbli pe căile Lui și să păzești poruncile Lui, legile și rânduielile Lui, ca să trăiești și să te înmulți și să te binecuvânteze Domnul Dumnezeul tău în țara în care intri ca să o stăpânești."],[17,"Dar dacă inima ta se întoarce și nu vei auzi, ci vei fi atras și te închini altor dumnezei și le slujești,"],[18,"Vă declar astăzi că veți pieri cu siguranță. Nu-ți vei prelungi zilele în țara pe care vei trece Iordanul ca să intri să-l stăpânești."],[19,"Chem astăzi cerul și pământul să mărturisească împotriva ta că ți-am pus înainte viața și moartea, binecuvântarea și blestemul. De aceea alege viața, ca să trăiești, tu și urmașii tăi,"],[20,"să iubești pe Domnul Dumnezeul tău, să asculți de glasul Lui și să te agăți de el; căci el este viața ta și lungimea zilelor tale, ca să locuiești în țara pe care DOMNUL a jurat-o părinților tăi, lui Avraam, lui Isaac și lui Iacov, că o va da lor."]]],[31,[[1,"Moise s-a dus și a spus aceste cuvinte întregului Israel."],[2,"El le-a zis: „Astăzi am o sută douăzeci de ani. Nu mai pot să ies și să intru. Domnul mi-a spus: „Să nu treceți Iordanul acesta”."],[3,"Însuși Domnul Dumnezeul tău va merge înaintea ta. El va nimici aceste națiuni dinaintea ta și le vei izgoni. Iosua va trece înaintea ta, după cum a spus Domnul."],[4,"Domnul le va face așa cum a făcut cu Sihon și cu Og, împărații amoriților, și cu țara lor, când i-a nimicit."],[5,"Domnul le va da înaintea voastră și le veți face după toată porunca pe care v-am poruncit."],[6,"Fii puternic și curajos. Nu-ți fie frică și nici nu te speria de ei, căci Domnul Dumnezeul tău însuși este Cel care merge cu tine. El nu te va dezamăgi și nu te va părăsi.”"],[7,"Moise a chemat pe Iosua și i-a zis în fața întregului Israel: „Fii tare și curajos, căci vei merge cu acest popor în țara pe care a jurat DOMNUL părinților săi că le-o va da și le vei lăsa să o moștenească."],[8,"Domnul însuși este cel care merge înaintea ta. El va fi cu tine. El nu te va dezamăgi și nici nu te va părăsi. nu-ți fie frică. Nu te descuraja.”"],[9,"Moise a scris această lege și a dat-o preoților, fiii lui Levi, care purtau chivotul legământului Domnului, și tuturor bătrânilor lui Israel."],[10,"Moise le-a poruncit, zicând: „La sfârşitul fiecărui şapte ani, la timpul stabilit al anului slobozirii, la sărbătoarea cortului,"],[11,"Când tot Israelul va veni să se înfățișeze înaintea Domnului Dumnezeului tău în locul pe care îl va alege, vei citi legea aceasta înaintea întregului Israel, în auzul lor."],[12,"Adună poporul, bărbații și femeile și micuții și străinii care sunt la porțile tale, ca să audă, să învețe, să se teamă de Domnul Dumnezeul tău și să păzească să împlinească toate cuvintele acestei legi,"],[13,"și pentru ca copiii lor, care nu au cunoscut, să audă și să învețe să se teamă de DOMNUL Dumnezeul tău, atâta timp cât vei locui în țara în care vei trece Iordanul ca să o stăpânești.”"],[14,"Domnul i-a zis lui Moise: „Iată, se apropie zilele tale în care trebuie să mori. Cheamă-te pe Iosua și te înfățișați în cortul întîlnirii, ca să-i dau încredințare.”"],[15,"Domnul S-a arătat în cort într-un stâlp de nor, iar stâlpul de nor stătea deasupra ușii Cortului."],[16,"Domnul a zis lui Moise: „Iată, vei dormi cu părinţii tăi. Poporul acesta se va ridica şi se va desfrâna după zeii străini ai ţării în care merg să fie printre ei, Mă va părăsi şi mă va rupe legământul pe care l-am încheiat cu ei."],[17,"Atunci mânia Mea se va aprinde împotriva lor în ziua aceea și îi voi părăsi și îmi voi ascunde fața de ei și vor fi mistuiți și multe rele și necazuri vor veni asupra lor; încât ei vor zice în ziua aceea: „Nu au venit oare aceste rele peste noi pentru că Dumnezeul nostru nu este printre noi?”"],[18,"Cu siguranță îmi voi ascunde fața în ziua aceea pentru tot răul pe care l-au făcut, prin aceea că s-au întors la alți dumnezei."],[19,"„Acum scrieți-vă acum cântecul acesta și învățați-l copiilor lui Israel și puneți-l în gura lor, pentru ca acest cântec să fie pentru mine mărturie împotriva copiilor lui Israel."],[20,"Căci când îi voi aduce în țara pe care am jurat-o părinților lor, în care curge lapte și miere, și ei vor mânca și se vor sătura și s-au îngrășat, atunci se vor întoarce la alți dumnezei și le vor sluji, Mă vor disprețui și vor încălca legământul Meu."],[21,"Se va întâmpla, când vor veni peste ei multe rele și necazuri, această cântare să mărturisească înaintea lor ca martor; căci nu va fi uitat din gura urmașilor lor; pentru că le cunosc căile și ce fac ei astăzi, înainte de a-i aduce în țara pe care le-am promis-o.”"],[22,"Deci Moise a scris acest cântec în aceeași zi și l-a învățat copiilor lui Israel."],[23,"El l-a însărcinat pe Iosua, fiul lui Nun, și a zis: „Fii tare și curajos, căci vei aduce pe copiii lui Israel în țara pe care le-am jurat; voi fi cu tine”."],[24,"Când Moise a terminat de scris cuvintele acestei legi într-o carte, până s-au terminat,"],[25,"Moise le-a poruncit leviților, care au purtat chivotul legământului Domnului, zicând:"],[26,"„Ia această carte a Legii și pune-o lângă chivotul Domnului, legământul Dumnezeului tău, ca să fie acolo ca martor împotriva ta."],[27,"Căci îți cunosc răzvrătirea și gâtul înțepenit. Iată, cât sunt încă în viață cu tine astăzi, ai fost răzvrătit împotriva Domnului. Cât mai mult după moartea mea?"],[28,"Adunați la mine pe toți bătrânii triburilor voastre și pe toți stăpânii voștri, ca să le spun aceste cuvinte în urechi și să chem mărturie împotriva lor cerul și pământul."],[29,"Căci știu că, după moartea mea, vă veți strica cu totul și vă veți abate de la calea pe care v-am poruncit; și ți se va întâmpla rău în zilele din urmă, pentru că vei face ceea ce este rău înaintea Domnului, ca să-l provoci la mânie prin lucrarea mâinilor tale.”"],[30,"Moise a rostit în urechile întregii adunări a lui Israel cuvintele acestei cântări, până s-au terminat."]]],[32,[[1,"Ascultați, ceruri, și voi vorbi."],[2,"Doctrina mea va cădea ca ploaia."],[3,"Căci voi vesti numele Domnului."],[4,"The Rock: lucrarea lui este perfectă,"],[5,"Au tratat corupt cu el."],[6,"Acesta este modul în care răsplătiți Domnului,"],[7,"Amintiți-vă de zilele de odinioară."],[8,"Când Cel Preaînalt a dat națiunilor moștenirea lor,"],[9,"Căci partea Domnului este poporul Său."],[10,"L-a găsit într-un pământ pustiu,"],[11,"Ca un vultur care-și stârnește cuibul,"],[12,"Doar Domnul l-a condus."],[13,"L-a făcut să călărească pe înălțimile pământului."],[14,"unt din turmă și lapte din turmă,"],[15,"Dar Jeshurun ​​s-a îngrășat și a dat cu piciorul."],[16,"L-au mutat la gelozie cu zei străini."],[17,"S-au sacrificat demonilor, nu lui Dumnezeu,"],[18,"De Stânca care ți-a devenit tată, nu ești atent,"],[19,"Domnul a văzut și a urât,"],[20,"El a spus: „Îmi voi ascunde fața de ei."],[21,"M-au indus la gelozie cu ceea ce nu este Dumnezeu."],[22,"Căci focul se aprinde în mânia mea,"],[23,"„Voi îngrămădi rele asupra lor."],[24,"Vor fi risipiti de foame,"],[25,"Afară sabia va lipsi,"],[26,"Am spus că le voi împrăștia departe."],[27,"dacă nu mă temeam de provocarea dușmanului,"],[28,"Căci ei sunt o națiune lipsită de sfat."],[29,"O, dacă ar fi înțelepți, dacă ar fi înțeles asta,"],[30,"Cum ar putea cineva să urmărească o mie,"],[31,"Căci stânca lor nu este ca Stânca noastră,"],[32,"Căci via lor este din via Sodomei,"],[33,"Vinul lor este otrava șerpilor,"],[34,"„Nu este asta ținut la mine,"],[35,"Răzbunarea este a mea și răsplata,"],[36,"Căci Domnul va judeca poporul Său,"],[37,"El va spune: „Unde sunt zeii lor,"],[38,"care au mâncat grăsimea jertfelor lor,"],[39,"„Vezi acum că eu sunt el."],[40,"Căci îmi ridic mâna la cer și spun:"],[41,"dacă îmi ascuți sabia strălucitoare,"],[42,"Îmi voi îmbăta săgețile cu sânge."],[43,"Bucurați-vă, neamuri, cu poporul lui,"],[44,"Moise a venit și a rostit toate cuvintele acestei cântări în urechile poporului, el și Iosua, fiul lui Nun."],[45,"Moise a terminat de recitat toate aceste cuvinte întregului Israel."],[46,"El le-a zis: „Puneți-vă inima la toate cuvintele pe care vi le mărturisesc astăzi și pe care le veți porunci copiilor voștri să se țină să le facă, toate cuvintele acestei legi."],[47,"Căci nu este un lucru zadarnic pentru tine, pentru că este viața ta și prin acest lucru îți vei prelungi zilele în țara, unde vei trece Iordanul ca să-l stăpânești.”"],[48,"Domnul a vorbit lui Moise în aceeași zi, zicând:"],[49,"„Suie-te pe acest munte Abarim, la muntele Nebo, care este în țara Moabului, care este vizavi de Ierihon, și vezi țara Canaanului, pe care o dau copiilor lui Israel ca stăpânire."],[50,"Mori pe muntele pe care te urci și fii adunat la poporul tău, precum Aaron, fratele tău, a murit pe muntele Hor și a fost adunat la poporul său;"],[51,"pentru că ai păcătuit împotriva mea printre copiii lui Israel, la apele Meriba din Cadeș, în pustia Țin; pentru că nu ai susținut sfințenia mea printre copiii lui Israel."],[52,"Căci vei vedea țara de la distanță; dar să nu mergeți acolo în țara pe care o dau copiilor lui Israel”."]]],[33,[[1,"Aceasta este binecuvântarea cu care Moise, omul lui Dumnezeu, i-a binecuvântat pe copiii lui Israel înainte de moartea sa."],[2,"El a spus,"],[3,"Da, iubește oamenii."],[4,"Moise ne-a poruncit o lege,"],[5,"El a fost rege în Jeshurun,"],[6,"„Lasă pe Ruben să trăiască și să nu moară;"],[7,"Aceasta este pentru Iuda. El a spus,"],[8,"Despre Levi a spus:"],[9,"El a spus despre tatăl său și despre mama lui: „Nu l-am văzut”."],[10,"Ei vor învăța pe Iacov rânduielile tale,"],[11,"Yahweh, binecuvântează-i abilitățile."],[12,"Despre Beniamin a spus:"],[13,"Despre Iosif a spus:"],[14,"pentru lucrurile prețioase ale fructelor soarelui,"],[15,"pentru cele mai bune lucruri ale munților antici,"],[16,"pentru lucrurile prețioase ale pământului și plinătatea lui,"],[17,"Majestatea aparține întâiului născut al turmei sale."],[18,"Despre Zabulon a spus:"],[19,"Ei vor chema popoarele la munte."],[20,"Despre Gad a spus:"],[21,"El și-a oferit prima parte,"],[22,"Despre Dan a spus:"],[23,"Despre Neftali a spus:"],[24,"Despre Asher a spus:"],[25,"Barele voastre vor fi din fier și bronz."],[26,"„Nu există nimeni ca Dumnezeu, Jeshurun,"],[27,"Dumnezeul veșnic este locuința ta."],[28,"Israelul locuiește în siguranță,"],[29,"Ești fericit, Israel!"]]],[34,[[1,"Moise s-a suit din câmpiile Moabului la muntele Nebo, pe vârful Pisga, care este vizavi de Ierihon. Domnul i-a arătat lui Dan toată țara Galaadului,"],[2,"și tot Neftali și țara lui Efraim și Manase și toată țara lui Iuda, până la Marea de Apus,"],[3,"iar la miazăzi și Câmpia văii Ierihonului, cetatea palmierii, până la Țoar."],[4,"Domnul i-a zis: „Aceasta este țara pe care am jurat lui Avraam, lui Isaac și lui Iacov, zicând: „O voi da semințelor tale.” Ți-am făcut să o vezi cu ochii tăi, dar nu vei trece acolo.”"],[5,"Astfel, Moise, slujitorul Domnului, a murit acolo, în țara Moabului, după cuvântul Domnului."],[6,"L-a îngropat în valea din țara Moabului, vizavi de Bet-Peor, dar nimeni nu știe unde este mormântul lui până în ziua de azi."],[7,"Moise avea o sută douăzeci de ani când a murit. Ochiul lui nu era stins și nici puterea nu i-a dispărut."],[8,"Copiii lui Israel au plâns pe Moise în câmpiile Moabului treizeci de zile, până când s-au sfârşit zilele de plâns în doliu pentru Moise."],[9,"Iosua, fiul lui Nun, era plin de duhul înțelepciunii, pentru că Moise își pusese mâinile peste el. Copiii lui Israel l-au ascultat și au făcut cum poruncise lui Moise Domnul."],[10,"De atunci, nu s-a mai ridicat în Israel un profet ca Moise, pe care Domnul l-a cunoscut față în față,"],[11,"în toate semnele și minunile pe care l-a trimis DOMNUL să le facă în țara Egiptului, lui Faraon și tuturor slujitorilor săi și în toată țara lui,"],[12,"și în toată mâna puternică și în toate faptele înfricoșătoare pe care le-a făcut Moise înaintea ochilor întregului Israel."]]]];